  const percentageSourceData = { "topic": "ટકાવારી (Percentage - Lecture 1 & Lecture 2 Complete)", "total_questions_count": 108, "notes_and_concepts": { "title": "ટકાવારી (Percentage) - ૧૦૦% સંપૂર્ણ કમ્પ્લીટ નોટ્સ અને પ્રશ્નોત્તરી", "concepts": [ { "concept_name": "અપૂર્ણાંક અને ટકાવારી રૂપાંતરણ કોષ્ટક (Fraction to Percentage Table)", "explanation": "ગણતરી ઝડપી કરવા માટે અપૂર્ણાંકનું ટકાવારીમાં સીધું મૂલ્ય યાદ રાખવું જરૂરી છે.", "rules": [ "1/1 = 100%", "1/2 = 50%", "1/3 = 33.33%", "1/4 = 25%", "1/5 = 20%", "1/6 = 16.66%", "1/7 = 14.28%", "1/8 = 12.5%", "1/9 = 11.11%", "1/10 = 10%", "1/11 = 9.09%", "1/12 = 8.33%", "2/3 = 66.66%", "3/8 = 37.5%", "5/8 = 62.5%" ] }, { "concept_name": "ટકાવારી સરખામણી અને બજેટ અચળ સૂત્રો", "explanation": "જ્યારે કોઈ વસ્તુના ભાવમાં x% વધારો કે ઘટાડો થાય અને ખર્ચ સમાન રાખવો હોય:", "formulas": [ "ભાવ વધારા પર વપરાશ ઘટાડો % = [x / (100 + x)] × 100", "ભાવ ઘટાડા પર વપરાશ વધારો % = [x / (100 - x)] × 100", "A ની આવક B કરતાં x% વધુ હોય તો B ની આવક A કરતાં ઓછી % = [x / (100 + x)] × 100", "A ની આવક B કરતાં x% ઓછી હોય તો B ની આવક A કરતાં વધુ % = [x / (100 - x)] × 100" ] }, { "concept_name": "ક્રમિક ટકાવારી ફેરફાર (Net Percentage Change)", "explanation": "જ્યારે કિંમતમાં સતત બે વાર ટકાવારી વધારો કે ઘટાડો થાય:", "formulas": [ "Net Change = a + b + (a × b / 100) %", "જો x% વધારો અને x% ઘટાડો થાય તો હંમેશાં ચોખ્ખો ઘટાડો જ થાય = (x² / 100) %" ] }, { "concept_name": "ચૂંટણી, વસ્તી, બજેટ અને ગુણ સંબધિત કન્સેપ્ટ", "explanation": "ચૂંટણીમાં મતોની ગણતરી 100% ધારીને, અમાન્ય મતો બાદ કરીને અથવા x ધારીને સાંકળ નિયમથી કરવી." } ] }, "questions": [ { "question_number": 1, "source": "ટકાવારી Lecture 1.pdf", "question_text": "5600 ના 28 ટકાનું મૂલ્ય કેટલું છે? (CCE 2023)", "options": { "A": "1548", "B": "1568", "C": "1588", "D": "1578" }, "correct_answer": "B", "explanation": "ગણતરી: 5600 × (28 / 100) = 56 × 28 = 1568." }, { "question_number": 2, "source": "ટકાવારી Lecture 1.pdf", "question_text": "120 ના કેટલા ટકા 90 છે? (CCE 2023)", "options": { "A": "75%", "B": "50%", "C": "25%", "D": "35%" }, "correct_answer": "A", "explanation": "ગણતરી: (90 / 120) × 100 = (3 / 4) × 100 = 75%." }, { "question_number": 3, "source": "ટકાવારી Lecture 1.pdf", "question_text": "999 ના 33 ટકાનું મૂલ્ય કેટલું છે? (CCE 2023)", "options": { "A": "328.67", "B": "325.37", "C": "326.37", "D": "329.67" }, "correct_answer": "D", "explanation": "ગણતરી: 999 × (33 / 100) = 32967 / 100 = 329.67." }, { "question_number": 4, "source": "ટકાવારી Lecture 1.pdf", "question_text": "16.30 લિટરના 82% શોધો. (CCE 2023)", "options": { "A": "10.335 લિટર", "B": "20.125 લિટર", "C": "13.366 લિટર", "D": "15.252 લિટર" }, "correct_answer": "C", "explanation": "ગણતરી: 16.30 × 82 / 100 = 1336.6 / 100 = 13.366 લિટર." }, { "question_number": 5, "source": "ટકાવારી Lecture 1.pdf", "question_text": "કઈ સંખ્યા 600 ના 60 ટકાના 70 ટકા છે? (CCE 2023)", "options": { "A": "252", "B": "242", "C": "262", "D": "272" }, "correct_answer": "A", "explanation": "ગણતરી: 600 × (60 / 100) × (70 / 100) = 600 × 0.6 × 0.7 = 252." }, { "question_number": 6, "source": "ટકાવારી Lecture 1.pdf", "question_text": "કઈ સંખ્યા 1300ના 10 ટકાના 25 ટકા છે? (CCE 2023)", "options": { "A": "32.5", "B": "36.5", "C": "24.5", "D": "40.5" }, "correct_answer": "A", "explanation": "ગણતરી: 1300 × (10 / 100) × (25 / 100) = 130 × (1/4) = 32.5." }, { "question_number": 7, "source": "ટકાવારી Lecture 1.pdf", "question_text": "1250 ના 50 ટકાના 60 ટકાનું મૂલ્ય કેટલું છે? (CCE 2023)", "options": { "A": "350", "B": "380", "C": "400", "D": "375" }, "correct_answer": "D", "explanation": "ગણતરી: 1250 × (1/2) × (3/5) = 625 × 3 / 5 = 375." }, { "question_number": 8, "source": "ટકાવારી Lecture 1.pdf", "question_text": "200 ના 25 ટકાના 425 ટકા = ________. (CCE 2023)", "options": { "A": "211.5", "B": "212.5", "C": "213.5", "D": "214.5" }, "correct_answer": "B", "explanation": "ગણતરી: 200 × (25 / 100) × (425 / 100) = 50 × 4.25 = 212.5." }, { "question_number": 9, "source": "ટકાવારી Lecture 1.pdf", "question_text": "1.28 ને 1.6ના ________ ટકા તરીકે દર્શાવી શકાય. (CCE 2023)", "options": { "A": "80%", "B": "92%", "C": "72%", "D": "85%" }, "correct_answer": "A", "explanation": "ગણતરી: (1.28 / 1.60) × 100 = (128 / 160) × 100 = (4 / 5) × 100 = 80%." }, { "question_number": 10, "source": "ટકાવારી Lecture 1.pdf", "question_text": "એક નગરની વસ્તી એક વર્ષમાં 42400 થી વધીને 48000 થાય છે. વસ્તીમાં કેટલા ટકા વધારો થયો છે? (CCE 2023)", "options": { "A": "12.50%", "B": "10.52%", "C": "21.33%", "D": "13.21%" }, "correct_answer": "D", "explanation": "વધારો = 48000 - 42400 = 5600. ટકાવારી વધારો = (5600 / 42400) × 100 = (1400 / 106) ≈ 13.21%." }, { "question_number": 11, "source": "ટકાવારી Lecture 1.pdf", "question_text": "અલીનો પગાર 6000 રૂપિયાથી વધીને 8000 રૂપિયા થયો. પગારમાં ટકાવારીમાં કેટલો વધારો થયો છે? (CCE 2023)", "options": { "A": "25%", "B": "23.33%", "C": "33.33%", "D": "20%" }, "correct_answer": "C", "explanation": "વધારો = 2000. ટકાવારી વધારો = (2000 / 6000) × 100 = 100 / 3 = 33.33%." }, { "question_number": 12, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જો કોઈ વ્યક્તિની માસિક આવકના 20% એ Rs. 4000 હોય, તેઓ દર મહિને ભાડા પર Rs. 6000 ખર્ચે તો તેઓ તેમની માસિક આવકના કેટલા ટકા ભાડા પર ખર્ચ કરે છે? (CCE 2023)", "options": { "A": "30%", "B": "50%", "C": "40%", "D": "20%" }, "correct_answer": "A", "explanation": "20% = 4000, તેથી માસિક આવક (100%) = 20000. ભાડા પર ખર્ચ = (6000 / 20000) × 100 = 30%." }, { "question_number": 13, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જો કોઈ વ્યક્તિની માસિક આવકના 15% એ Rs. 3000 થાય, અને તે દર મહિને કરિયાણા પર Rs. 4500 ખર્ચે તો તેની માસિક આવકના કેટલા ટકા તે કરિયાણા પર ખર્ચ કરે છે? (CCE 2023)", "options": { "A": "27.5%", "B": "15%", "C": "22.5%", "D": "25%" }, "correct_answer": "C", "explanation": "15% = 3000, તેથી માસિક આવક = 20000. કરિયાણા પર ખર્ચ % = (4500 / 20000) × 100 = 22.5%." }, { "question_number": 14, "source": "ટકાવારી Lecture 1.pdf", "question_text": "ત્રણ વિદ્યાર્થીઓ વચ્ચેની એક ચૂંટણીમાં તેઓને અનુક્રમે 4000, 8000 અને 20000 મતો મળ્યા હતા. જણાવો કે વિજેતા વિદ્યાર્થીને મળતા કુલ મતોની ટકાવારી કેટલી થાય? (CCE 2023)", "options": { "A": "45.8%", "B": "60.9%", "C": "62.5%", "D": "55.5%" }, "correct_answer": "C", "explanation": "કુલ મત = 4000 + 8000 + 20000 = 32000. વિજેતાને મળેલ મત = 20000. ટકાવારી = (20000 / 32000) × 100 = 62.5%." }, { "question_number": 15, "source": "ટકાવારી Lecture 1.pdf", "question_text": "એક સર્વેક્ષણમાં, 63% ઉત્તરદાતાઓએ ઉત્પાદન A ને પસંદ કર્યું. જો કુલ 1,500 ઉત્તરદાતાઓ હતા, તો કેટલા ઉત્તરદાતાઓએ ઉત્પાદન A ને પસંદ કર્યું? (CCE 2023)", "options": { "A": "945", "B": "955", "C": "825", "D": "645" }, "correct_answer": "A", "explanation": "ગણતરી: 1500 × 63 / 100 = 15 × 63 = 945." }, { "question_number": 16, "source": "ટકાવારી Lecture 1.pdf", "question_text": "સૂર્ય 10% કેળા અને 30% સફરજન ખાતો હતો. જો ત્યાં 60 કેળા અને 50 સફરજન હતા, તો તેણે કેટલા ફળ ખાધા હશે? (CCE 2023)", "options": { "A": "21", "B": "25", "C": "18", "D": "15" }, "correct_answer": "A", "explanation": "ખાધેલા કેળા = 60 ના 10% = 6. ખાધેલા સફરજન = 50 ના 30% = 15. કુલ ફળ = 6 + 15 = 21." }, { "question_number": 17, "source": "ટકાવારી Lecture 1.pdf", "question_text": "શાળાના પ્રમુખપદની ચૂંટણીમાં, એક ઉમેદવારે કુલ 1,350 મતોમાંથી 58% મેળવ્યા છે. તેને કેટલા મત મળ્યા? (CCE 2023)", "options": { "A": "800 વોટ", "B": "756 વોટ", "C": "700 વોટ", "D": "783 વોટ" }, "correct_answer": "D", "explanation": "ગણતરી: 1350 × 58 / 100 = 135 × 5.8 = 783 વોટ." }, { "question_number": 18, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જો A ના 42 ટકા + 350 ના 12 ટકા = 700 ના 24 ટકા હોય, તો A નું મૂલ્ય શું છે? (CCE 2023)", "options": { "A": "350", "B": "330", "C": "400", "D": "300" }, "correct_answer": "D", "explanation": "A × 0.42 + 42 = 168 ⇒ A × 0.42 = 126 ⇒ A = 126 / 0.42 = 300." }, { "question_number": 19, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જ્યારે સંખ્યાના 50% માં 40 ઉમેરવામાં આવે છે, ત્યારે જવાબ એ સંખ્યા છે. સંખ્યાનો વર્ગ શોધો. (CCE 2023)", "options": { "A": "6400", "B": "2500", "C": "3600", "D": "4000" }, "correct_answer": "A", "explanation": "x/2 + 40 = x ⇒ x/2 = 40 ⇒ x = 80. સંખ્યાનો વર્ગ x² = 80² = 6400." }, { "question_number": 20, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જો આપેલ બે સંખ્યાઓ ત્રીજી સંખ્યાના અનુક્રમે 6% અને 18% હોય, તો પ્રથમ સંખ્યા એ બીજી સંખ્યાના કેટલા ટકા છે? (CCE 2023)", "options": { "A": "33.33%", "B": "25%", "C": "35.5%", "D": "28%" }, "correct_answer": "A", "explanation": "પ્રથમ સંખ્યા = 6, બીજી = 18. ટકાવારી = (6 / 18) × 100 = 1/3 × 100 = 33.33%." }, { "question_number": 21, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જો જહોને એક પુસ્તક 0.35 જેટલું વાંચ્યું હોય અને મારિયાએ જો 25% વાંચ્યું હોય, તો કોણે વધુ વાંચ્યું છે અને તે અપૂર્ણાંકમાં કેટલું થાય? (CCE 2023)", "options": { "A": "જહોને, 1/20 જેટલું", "B": "મારિયા, 1/20 જેટલું", "C": "મારિયા, 1/10 જેટલું", "D": "જહોને, 1/10 જેટલું" }, "correct_answer": "D", "explanation": "જહોન = 0.35 = 35%, મારિયા = 25%. જહોને વધુ વાંચ્યું. તફાવત = 35% - 25% = 10% = 1/10." }, { "question_number": 22, "source": "ટકાવારી Lecture 1.pdf", "question_text": "2400 ના 16% અને 1800 ના 16% વચ્ચેનો તફાવત શું છે? (CCE 2023)", "options": { "A": "96", "B": "80", "C": "85", "D": "74" }, "correct_answer": "A", "explanation": "તફાવત = (2400 - 1800) ના 16% = 600 ના 16% = 96." }, { "question_number": 23, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જો કોઈ સંખ્યાના 20 ટકાના 20 ટકા બરાબર 124 હોય, તો તે સંખ્યાના 31 ટકા કેટલા છે? (CCE 2023)", "options": { "A": "961", "B": "991", "C": "971", "D": "951" }, "correct_answer": "A", "explanation": "x × 1/5 × 1/5 = 124 ⇒ x = 124 × 25 = 3100. 3100 ના 31% = 31 × 31 = 961." }, { "question_number": 24, "source": "ટકાવારી Lecture 1.pdf", "question_text": "K ની આવકના 10 ટકા એ I ની આવકના 25 ટકા બરાબર છે. જો K ની આવક Rs. 17500 હોય, તો I ની આવક કેટલી છે? (CCE 2023)", "options": { "A": "Rs. 7700", "B": "Rs. 70000", "C": "Rs. 7070", "D": "Rs. 7000" }, "correct_answer": "D", "explanation": "17500 ના 10% = I ના 25% ⇒ 1750 = I × (1/4) ⇒ I = 1750 × 4 = 7000." }, { "question_number": 25, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જો M ના M ટકા 9409 છે, તો M² નું મૂલ્ય કેટલું હશે? (CCE 2023)", "options": { "A": "940090", "B": "940000", "C": "940900", "D": "944900" }, "correct_answer": "C", "explanation": "M × M / 100 = 9409 ⇒ M² / 100 = 9409 ⇒ M² = 940900." }, { "question_number": 26, "source": "ટકાવારી Lecture 1.pdf", "question_text": "T1 ની 20 ટકા = T2 ના 25 ટકા અને T2 = T1ના b ટકા છે. b નું મૂલ્ય શું છે? (CCE 2023)", "options": { "A": "60", "B": "120", "C": "80", "D": "95" }, "correct_answer": "C", "explanation": "T1 × 0.20 = T2 × 0.25 ⇒ T2 = (20/25) × T1 = 0.80 × T1 = T1 ના 80%. તેથી b = 80." }, { "question_number": 27, "source": "ટકાવારી Lecture 1.pdf", "question_text": "T1 ની આવકના 15 ટકા T2ની આવકના 23 ટકા જેટલા છે. જો T1ની આવક Rs 52900 હોય, તો T2ની આવક કેટલી છે? (CCE 2023)", "options": { "A": "Rs. 35540", "B": "Rs. 34500", "C": "Rs. 35450", "D": "Rs. 35500" }, "correct_answer": "B", "explanation": "52900 × 15 = T2 × 23 ⇒ T2 = 2300 × 15 = 34500." }, { "question_number": 28, "source": "ટકાવારી Lecture 1.pdf", "question_text": "જો U એ V કરતાં 25 ટકા ઓછો છે અને V એ 640 કરતાં 20 ટકા વધુ હોય, તો U નું મૂલ્ય શું છે? (CCE 2023)", "options": { "A": "676", "B": "576", "C": "666", "D": "566" }, "correct_answer": "B", "explanation": "V = 640 × 1.20 = 768. U = 768 × 0.75 = 576." }, { "question_number": 29, "source": "ટકાવારી Lecture 1.pdf", "question_text": "પરી દર મહિને તેના પગારના 20% બચાવે છે. અને આમ તે વર્ષના અંતે ₹20000 બચાવી શકે છે. તેનીનો વાર્ષિક પગાર શોધો. (CCE 2023)", "options": { "A": "₹ 80,000", "B": "₹ 1,20,000", "C": "₹ 60,000", "D": "₹ 1,00,000" }, "correct_answer": "D", "explanation": "વાર્ષિક બચત = વાર્ષિક પગારના 20% = 20000. વાર્ષિક પગાર = 20000 × 5 = 1,00,000." }, { "question_number": 30, "source": "ટકાવારી Lecture 1.pdf", "question_text": "સુનીલની આવક ₹20000 છે. જો તે તેની આવકના 45% ખર્ચ કરે, તો તે કેટલી રકમ બચાવે છે તે શોધો. (CCE 2023)", "options": { "A": "₹12000", "B": "₹11000", "C": "₹9000", "D": "₹10000" }, "correct_answer": "B", "explanation": "બચત % = 100% - 45% = 55%. બચત રકમ = 20000 ના 55% = 11000." }, { "question_number": 31, "source": "ટકાવારી Lecture 1.pdf", "question_text": "પ્રાચીની બચત તેના ખર્ચના 20% છે. જો પ્રાચીની વાર્ષિક આવક ₹18,00,000 હોય. તો તેનીનો માસિક ખર્ચ શોધો. (CCE 2023)", "options": { "A": "₹1,15,000", "B": "₹ 1,00,000", "C": "₹ 75,000", "D": "₹1,25,000" }, "correct_answer": "D", "explanation": "માસિક આવક = 18,00,000 / 12 = 1,50,000. ખર્ચ = 100, બચત = 20, આવક = 120. 120 ભાગ = 1,50,000 ⇒ ખર્ચ (100 ભાગ) = 1,25,000." }, { "question_number": 32, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં, વિજેતાને 52% મત મળે છે. જો કુલ મત 40,000 હોય. તો હારેલા ઉમેદવારે મેળવેલા મતો શોધો. (CCE 2023)", "options": { "A": "17400", "B": "18400", "C": "19200", "D": "20400" }, "correct_answer": "C", "explanation": "હારેલા ઉમેદવારના મત % = 100% - 52% = 48%. મતોની સંખ્યા = 40000 ના 48% = 19200." }, { "question_number": 33, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં, રામને કુલ માન્ય મતોમાંથી 3600 મળ્યા. જો રાઘવને મળેલા મતોની સંખ્યા 40% છે. કુલ માન્ય મતો શોધો. (CCE 2023)", "options": { "A": "8000", "B": "10000", "C": "9000", "D": "6000" }, "correct_answer": "D", "explanation": "રામના મત % = 100% - 40% = 60%. 60% = 3600 ⇒ કુલ માન્ય મત (100%) = 6000." }, { "question_number": 34, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં વિજેતા ઉમેદવારે 90% મત મેળવ્યા છે અને 72000 મતોથી જીત મેળવી છે. હારેલા ઉમેદવારોને કેટલા મત મળે છે? (CCE 2023)", "options": { "A": "9000", "B": "7200", "C": "6000", "D": "8800" }, "correct_answer": "A", "explanation": "જીતનું માર્જિન = 90% - 10% = 80%. 80% = 72000 ⇒ 10% (હારેલા ઉમેદવારના મત) = 9000." }, { "question_number": 35, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવાર વચ્ચેની ચૂંટણીમાં વિજેતા ઉમેદવારને 55 ટકા મત મળ્યા હતા. જો કુલ 2200 મત હોય, તો વિજેતા ઉમેદવારને કેટલા મત મળ્યા? (CCE 2023)", "options": { "A": "1,430", "B": "1,110", "C": "1,320", "D": "1,210" }, "correct_answer": "D", "explanation": "વિજેતાના મત = 2200 ના 55% = 22 × 55 = 1210." }, { "question_number": 36, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં, અર્જુનને કુલ માન્ય મતોના 28% મળ્યા. જો કુલ મતોની સંખ્યા 4800 હતી, તો સાક્ષીને માન્ય મતોની સંખ્યા કેટલી હતી? (CCE 2023)", "options": { "A": "3484", "B": "3448", "C": "3456", "D": "3498" }, "correct_answer": "C", "explanation": "સાક્ષીના મત % = 100% - 28% = 72%. મતોની સંખ્યા = 4800 ના 72% = 48 × 72 = 3456." }, { "question_number": 37, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં, દીપમને કુલ માન્ય મતોમાંથી 7200 મત મળ્યા. જો રાકેશને મળેલા મતોની સંખ્યા 25% છે. કુલ માન્ય મતો શોધો. (CCE 2023)", "options": { "A": "28800", "B": "18600", "C": "9600", "D": "12500" }, "correct_answer": "C", "explanation": "દીપમના મત % = 100% - 25% = 75%. 75% = 7200 ⇒ કુલ માન્ય મત (100%) = 9600." }, { "question_number": 38, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવારો કિરણ અને સુદેશ વચ્ચેની ચૂંટણીમાં કિરણને કુલ મતોના 60% મત મળ્યા હતા. જો કુલ મતોની સંખ્યા 8000 હોય, તો સુદેશને મળેલા મતોની સંખ્યા શોધો. (CCE 2023)", "options": { "A": "2400", "B": "1800", "C": "3800", "D": "3200" }, "correct_answer": "D", "explanation": "સુદેશના મત % = 100% - 60% = 40%. મતોની સંખ્યા = 8000 ના 40% = 3200." }, { "question_number": 39, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં આરવનને કુલ માન્ય મતોમાંથી 9548 મત મળ્યા. જો ફાતિમાને મળેલા મતોની સંખ્યા 38% છે. તો કુલ માન્ય મતો શોધો. (CCE 2023)", "options": { "A": "15300", "B": "15500", "C": "15600", "D": "15400" }, "correct_answer": "D", "explanation": "આરવનના મત % = 100% - 38% = 62%. 62% = 9548 ⇒ કુલ માન્ય મત = 9548 / 0.62 = 15400." }, { "question_number": 40, "source": "ટકાવારી Lecture 1.pdf", "question_text": "બે ઉમેદવારો વચ્ચે યોજાયેલી ચૂંટણીમાં સનમને કુલ માન્ય મતોમાંથી 8400 મત મળ્યા હતા. જો રોશનને મળેલા મતોની સંખ્યા 16% છે. કુલ માન્ય મતો શોધો. (CCE 2023)", "options": { "A": "12000", "B": "16000", "C": "14000", "D": "10000" }, "correct_answer": "D", "explanation": "સનમના મત % = 100% - 16% = 84%. 84% = 8400 ⇒ કુલ માન્ય મત = 10000." }, { "question_number": 41, "source": "ટકાવારી Lecture 2.pdf", "question_text": "ધન સંખ્યાના 20% અને તે જ સંખ્યાના 25% નો સરવાળો 162 છે. તે સંખ્યાનો એક તૃતીયાંશ કેટલું થાય? (CCE 2023)", "options": { "A": "80", "B": "95", "C": "120", "D": "110" }, "correct_answer": "C", "explanation": "45% = 162 ⇒ મૂળ સંખ્યા (100%) = 360. સંખ્યાનો એક તૃતીયાંશ = 360 / 3 = 120." }, { "question_number": 42, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો જેકબે અસાઇનમેન્ટનો 5/7 ભાગ પૂર્ણ કર્યો હોય અને ઓલિવિયાએ 60% ભાગ પૂર્ણ કર્યો હોય, તો કોણે વધુ અને કેટલા ભાગનું પૂર્ણ કર્યું છે? (CCE 2023)", "options": { "A": "જેકબ, 4/35 જેટલું", "B": "ઓલિવિયા, 4/35 જેટલું", "C": "ઓલિવિયા, 1/20 જેટલું", "D": "જેકબ, 1/18 જેટલું" }, "correct_answer": "A", "explanation": "જેકબ = 5/7, ઓલિવિયા = 60% = 3/5. તફાવત = 5/7 - 3/5 = (25 - 21) / 35 = 4/35. જેકબે વધુ પૂર્ણ કર્યું." }, { "question_number": 43, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો અહમદ ₹ 2800 માં એક ઘડિયાળ ખરીદે છે અને 16% વેચાણ વેરો ચૂકવે છે. તો ખરીદી પર ખર્ચવામાં આવેલી કુલ રકમ ____________ છે. (CCE 2023)", "options": { "A": "₹ 2456", "B": "₹ 3248", "C": "₹ 5410", "D": "₹ 3380" }, "correct_answer": "B", "explanation": "કુલ રકમ = 2800 × 116 / 100 = 28 × 116 = 3248." }, { "question_number": 44, "source": "ટકાવારી Lecture 2.pdf", "question_text": "વિદ્યાર્થી Lને વિદ્યાર્થી M કરતા 60 ગુણ વધુ મળ્યા અને Lના ગુણ તેમના ગુણોના સરવાળાના 65 ટકા જેટલા હતા. L અને M એ અનુક્રમે મેળવેલા ગુણ કેટલા છે? (CCE 2023)", "options": { "A": "120, 50", "B": "150, 80", "C": "130, 70", "D": "100, 40" }, "correct_answer": "C", "explanation": "L = 65%, M = 35%. તફાવત (30%) = 60 ⇒ 1% = 2. L ના ગુણ (65%) = 130, M ના ગુણ (35%) = 70." }, { "question_number": 45, "source": "ટકાવારી Lecture 2.pdf", "question_text": "વિદ્યાર્થી અરુણને વિદ્યાર્થી વરુણ કરતા 25 ગુણ વધુ મળ્યા અને અરુણના ગુણ તેમના ગુણોના સરવાળાના 60 ટકા બરાબર હતા. અરુણ અને વરુણ દ્વારા અનુક્રમે કેટલા ગુણ મેળવવામાં આવ્યા? (CCE 2023)", "options": { "A": "95, 25", "B": "75, 50", "C": "100, 30", "D": "120, 50" }, "correct_answer": "B", "explanation": "અરુણ = 60%, વરુણ = 40%. તફાવત (20%) = 25 ⇒ 1% = 1.25. અરુણ = 75, વરુણ = 50." }, { "question_number": 46, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બે સંખ્યાઓ વચ્ચેનો તફાવત 1420 છે. જો એક સંખ્યાનો 6% એ બીજી સંખ્યાના 10% હોય, તો બે સંખ્યાઓ શોધો. (CCE 2023)", "options": { "A": "3980, 4550", "B": "3550, 2130", "C": "4420, 2030", "D": "5630, 2450" }, "correct_answer": "B", "explanation": "0.06 × A = 0.10 × B ⇒ A/B = 5/3. તફાવત (2 ભાગ) = 1420 ⇒ 1 ભાગ = 710. A = 3550, B = 2130." }, { "question_number": 47, "source": "ટકાવારી Lecture 2.pdf", "question_text": "મોહિતે શોપિંગ માટે લીધેલા પૈસામાંથી 30% પૈસા ખર્ચ કર્યા પછી તેની પાસે $2940 બચ્યા હતા. તે તેની સાથે કેટલા રૂપિયા લઈ ગયો હતો? (CCE 2023)", "options": { "A": "$ 3300", "B": "$ 2100", "C": "$ 4200", "D": "$ 4000" }, "correct_answer": "C", "explanation": "બચત % = 70%. 70% = 2940 ⇒ કુલ રકમ (100%) = 4200." }, { "question_number": 48, "source": "ટકાવારી Lecture 2.pdf", "question_text": "સેમ તેની માસિક આવકના 24% ઘરેલું ખર્ચમાં, 16% મનોરંજન પર, 10% શિક્ષણ પર ખર્ચે છે અને બાકીની બચત કરે છે. જો તેની બચત Rs.500 છે તો તેનો માસિક પગાર કેટલો છે? (CCE 2023)", "options": { "A": "Rs 500", "B": "Rs 2000", "C": "Rs 1000", "D": "Rs.1500" }, "correct_answer": "C", "explanation": "કુલ ખર્ચ = 24 + 16 + 10 = 50%. બચત % = 50%. 50% = 500 ⇒ માસિક પગાર = 1000." }, { "question_number": 49, "source": "ટકાવારી Lecture 2.pdf", "question_text": "વિકાસ તેની આવકના 5 ટકા શાળાને દાન કરે છે અને બાકીના 70 ટકા તેની બેંકમાં જમા કરે છે. જો હાલ તેની પાસે Rs. 6384 હોય, તો વિકાસની આવક કેટલી છે? (CCE 2023)", "options": { "A": "Rs. 20400", "B": "Rs. 21400", "C": "Rs. 24400", "D": "Rs. 22400" }, "correct_answer": "D", "explanation": "x × (95 / 100) × (30 / 100) = 6384 ⇒ x × 0.285 = 6384 ⇒ x = 22400." }, { "question_number": 50, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક પરીક્ષામાં વિરાટને 20 ટકા ગુણ મળ્યા હતા. તેને 65 ગુણ મળ્યા છે. તો પરીક્ષાના મહત્તમ ગુણ કેટલા હશે? (CCE 2023)", "options": { "A": "225", "B": "525", "C": "325", "D": "425" }, "correct_answer": "C", "explanation": "20% = 65 ⇒ મહત્તમ ગુણ (100%) = 65 × 5 = 325." }, { "question_number": 51, "source": "ટકાવારી Lecture 2.pdf", "question_text": "આધ્યાને તેની ફી ભરવા માટે ₹ 950ની જરૂર છે. તેણીએ તેના ભાઈ પાસેથી 20% ઉધાર લીધા હતા અને બાકીના 30% તેની માતા દ્વારા ભંડોળ આપવામાં આવ્યું હતું. તેનીની બેંકમાં તેની પાસે ₹ 300 હતા. તેનીને કેટલા રૂપિયા(માં)ની જરૂર પડશે? (CCE 2023)", "options": { "A": "₹ 232", "B": "₹ 160", "C": "₹ 190", "D": "₹ 200" }, "correct_answer": "A", "explanation": "ભાઈ પાસેથી લીધા પછી બાકી = 80%. માતા પાસેથી લીધા પછી બાકી = 70%. બાકી જરૂરિયાત = 950 × 0.8 × 0.7 = 532. બેંકમાં ₹300 હતા. વધારાની જરૂરિયાત = 532 - 300 = 232." }, { "question_number": 52, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો કોઈ વ્યક્તિ તેની માસિક આવકના 30% ભાડા પર ખર્ચ કરે છે અને બાકીની બચત કરે છે અને તેનું માસિક ભાડું ₹6000 છે, તો તેની માસિક આવક કેટલી છે? (CCE 2023)", "options": { "A": "₹30000", "B": "₹25000", "C": "₹20000", "D": "₹15000" }, "correct_answer": "C", "explanation": "30% = 6000 ⇒ માસિક આવક (100%) = 20000." }, { "question_number": 53, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો એક કુટુંબની માસિક આવકના 40% રકમ ગીરોની ચૂકવણી માટે વપરાય છે, અને તેઓ દર મહિને ગીરો પર Rs.2,400 ચૂકવે છે, તો તેમની કુલ માસિક આવક કેટલી છે? (CCE 2023)", "options": { "A": "Rs.5,000", "B": "Rs.6,000", "C": "Rs.8,000", "D": "Rs.7,000" }, "correct_answer": "B", "explanation": "40% = 2400 ⇒ માસિક આવક (100%) = 6000." }, { "question_number": 54, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક પરિવાર તેની માસિક આવકના 30% ઉપયોગિતાઓ પર ખર્ચ કરે છે. જો દર મહિને ઉપયોગિતાઓ પર Rs.900 ખર્ચવામાં આવે, તો પરિવારની કુલ માસિક આવક કેટલી છે? (CCE 2023)", "options": { "A": "Rs.4,000", "B": "Rs.3,000", "C": "Rs.3,500", "D": "Rs.2,000" }, "correct_answer": "B", "explanation": "30% = 900 ⇒ માસિક આવક (100%) = 3000." }, { "question_number": 55, "source": "ટકાવારી Lecture 2.pdf", "question_text": "પંકજ પોતાના માસિક પગારનો 20% હિસ્સો ઘરના ભાડા પાછળ ખર્ચે છે અને બાકીનો 20% હિસ્સો બાળકોના ભણતર પાછળ ખર્ચે છે. બાકીના 20%, તે ખોરાક પર ખર્ચ કરે છે અને બાકીની રકમની બચત કરે છે. જો તે દર વર્ષે Rs 4,80,000 ની બચત કરતો હોય તો તેની માસિક આવક કેટલી છે? (CCE 2023)", "options": { "A": "Rs. 4,00,000", "B": "Rs. 78,125", "C": "Rs. 88,420", "D": "Rs. 1,00,000" }, "correct_answer": "B", "explanation": "માસિક બચત = 4,80,000 / 12 = 40,000. x × (4/5) × (4/5) × (4/5) = 40,000 ⇒ x × (64 / 125) = 40,000 ⇒ x = 78,125." }, { "question_number": 56, "source": "ટકાવારી Lecture 2.pdf", "question_text": "વિકાસ તેની માસિક આવકના 20% ભાડા પર, 15% ખોરાક પર અને 30% ઘરની અન્ય પ્રવૃત્તિઓમાં ખર્ચે છે. બાકીની રકમ તે બચાવે છે. જો તેની માસિક આવક ₹40000 હોય, તો તેની વાર્ષિક બચત શોધો. (CCE 2023)", "options": { "A": "₹1,54,000", "B": "₹1,22,000", "C": "₹1,72,000", "D": "₹ 1,68,000" }, "correct_answer": "D", "explanation": "બચત % = 100 - (20 + 15 + 30) = 35%. માસિક બચત = 40000 ના 35% = 14000. વાર્ષિક બચત = 14000 × 12 = 1,68,000." }, { "question_number": 57, "source": "ટકાવારી Lecture 2.pdf", "question_text": "આદર્શ તેની માસિક આવકના 35% ઘરગથ્થુ ખર્ચમાં, 10% મનોરંજન પર, 15% શિક્ષણ પાછળ ખર્ચે છે અને બાકીની બચત કરે છે. જો તેની બચત Rs. 1000 હોય, તો તેનો માસિક પગાર કેટલો છે? (CCE 2023)", "options": { "A": "Rs 3000", "B": "Rs 2000", "C": "Rs 2500", "D": "Rs 1500" }, "correct_answer": "B", "explanation": "બચત % = 100 - (35 + 10 + 15) = 40%. 40% = 1000 ⇒ માસિક પગાર (100%) = 2500." }, { "question_number": 58, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો એક કંપનીની માસિક આવકના 25% ટેકનોલોજી અધતન (અપગ્રેડ) કરવા માટે ફાળવવામાં આવે છે અને તે દર મહિને આ અપગ્રેડ પર Rs. 5,000 ખર્ચ કરે છે, તો કંપનીની કુલ માસિક આવક કેટલી છે? (CCE 2023)", "options": { "A": "Rs.20000", "B": "Rs.15000", "C": "Rs.25000", "D": "Rs.18000" }, "correct_answer": "A", "explanation": "25% = 5000 ⇒ માસિક આવક (100%) = 20000." }, { "question_number": 59, "source": "ટકાવારી Lecture 2.pdf", "question_text": "U એ V ના 11 ગણા છે. તો V એ U કરતાં કેટલા ટકા ઓછો છે તે શોધો. (CCE 2023)", "options": { "A": "90.90 ટકા", "B": "9.09 ટકા", "C": "90 ટકા", "D": "9 ટકા" }, "correct_answer": "A", "explanation": "V = 1, U = 11. તફાવત = 10. ટકાવારી ઓછી = (10 / 11) × 100 = 90.90%." }, { "question_number": 60, "source": "ટકાવારી Lecture 2.pdf", "question_text": "રસોઈના તેલના ભાવમાં 35% જેટલો વધારો થયો છે. કોઈ પરિવારે રસોઈના તેલના વપરાશમાં કેટલા ટકા ઘટાડો કરવો જોઈએ કે જેથી આના કારણે તેમના ખર્ચમાં કોઈ વધારો ન થાય? (CCE 2023)", "options": { "A": "36.5%", "B": "30%", "C": "25.9%", "D": "20%" }, "correct_answer": "C", "explanation": "ઘટાડો % = (35 / 135) × 100 = (7 / 27) × 100 = 700 / 27 ≈ 25.9%." }, { "question_number": 61, "source": "ટકાવારી Lecture 2.pdf", "question_text": "કેજરીની આવક દીપક કરતા 28% વધુ છે. દીપકની આવક કેજરી કરતાં કેટલા ટકા ઓછી છે? (CCE 2023)", "options": { "A": "28%", "B": "25.4%", "C": "21.9%", "D": "78.1%" }, "correct_answer": "C", "explanation": "ઓછી % = (28 / 128) × 100 = (7 / 32) × 100 = 700 / 32 ≈ 21.9%." }, { "question_number": 62, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો કિંમતમાં 45 ટકાનો ઘટાડો થાય, તો વપરાશમાં કેટલા ટકાનો વધારો કરવો જોઈએ, જેથી ખર્ચ સમાન રહે? (CCE 2023)", "options": { "A": "81.81 ટકા", "B": "18.18 ટકા", "C": "33.33 ટકા", "D": "75.75 ટકા" }, "correct_answer": "A", "explanation": "વધારો % = (45 / 55) × 100 = (9 / 11) × 100 = 81.81%." }, { "question_number": 63, "source": "ટકાવારી Lecture 2.pdf", "question_text": "વિક્રમનો પગાર રવિના પગાર કરતાં 40% વધુ છે. રવિનો પગાર વિક્રમના પગાર કરતાં અંદાજે કેટલો ઓછો છે? (CCE 2023)", "options": { "A": "24.8%", "B": "26.5%", "C": "28.5%", "D": "21%" }, "correct_answer": "C", "explanation": "ઓછો % = (40 / 140) × 100 = (2 / 7) × 100 = 28.57% ≈ 28.5%." }, { "question_number": 64, "source": "ટકાવારી Lecture 2.pdf", "question_text": "અનુજનો પગાર બીજુના પગાર કરતા 40% વધારે છે. બીજુનો પગાર અનુજના પગાર કરતા કેટલા ટકા ઓછો છે (એક દશાંશ સ્થાન સુધીનો સાચો જવાબ) ? (CCE 2023)", "options": { "A": "28.57%", "B": "28.72%", "C": "28.88%", "D": "28.95%" }, "correct_answer": "A", "explanation": "ઓછો % = (40 / 140) × 100 = 28.57%." }, { "question_number": 65, "source": "ટકાવારી Lecture 2.pdf", "question_text": "રમેશનો પગાર સુરેશના પગાર કરતાં 18% ઓછો છે. રમેશના પગાર કરતાં સુરેશનો પગાર આશરે કેટલા ટકા વધારે છે? (CCE 2023)", "options": { "A": "22%", "B": "24%", "C": "16%", "D": "18%" }, "correct_answer": "A", "explanation": "વધારે % = (18 / 82) × 100 = 1800 / 82 ≈ 21.95% ≈ 22%." }, { "question_number": 66, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો y x થી 20.5% જેટલો વધી જાય. તો x એ y કરતા કેટલો ઓછો છે? (CCE 2023)", "options": { "A": "17.01%", "B": "11.00%", "C": "12.05%", "D": "10.33%" }, "correct_answer": "A", "explanation": "ઓછો % = (20.5 / 120.5) × 100 = (205 / 1205) × 100 = 17.01%." }, { "question_number": 67, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો y એ x કરતા 28.5% વધી જાય, તો x એ y કરતા કેટલો ઓછો હશે? (CCE 2023)", "options": { "A": "16.67%", "B": "22.18%", "C": "21.45%", "D": "19.23%" }, "correct_answer": "B", "explanation": "ઓછો % = (28.5 / 128.5) × 100 = 22.18%." }, { "question_number": 68, "source": "ટકાવારી Lecture 2.pdf", "question_text": "ચોખાની કિંમત 8.20% થી ઘટી ગઈ. તો વ્યક્તિ કેટલા ટકાથી ચોખાનો વપરાશ વધારી શકે છે કે જેથી તેના આખા બજેટમાં કોઈ ફેરફાર ન થાય? (CCE 2023)", "options": { "A": "8.93%", "B": "7.81%", "C": "6.50%", "D": "7.75%" }, "correct_answer": "A", "explanation": "વધારા % = (8.20 / (100 - 8.20)) × 100 = (8.20 / 91.80) × 100 = 8.93%." }, { "question_number": 69, "source": "ટકાવારી Lecture 2.pdf", "question_text": "રાઘવના નફામાં એક સપ્તાહમાં 10%નો વધારો થયો છે. તે પછી આગામી સપ્તાહમાં તે વધુ 20% વધ્યો. તો નફામાં થયેલો કુલ વધારો ________ છે. (CCE 2023)", "options": { "A": "32%", "B": "15%", "C": "20%", "D": "30%" }, "correct_answer": "A", "explanation": "કુલ વધારો = 10 + 20 + (10 × 20 / 100) = 30 + 2 = 32%." }, { "question_number": 70, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બેગની કિંમતમાં 30 ટકાનો ઘટાડો કરવાથી તેનું વેચાણ 50 ટકા વધી જાય છે. તેની આવકમાં કેટલા ટકાનો વધારો થશે? (CCE 2023)", "options": { "A": "25 ટકા", "B": "5 ટકા", "C": "10 ટકા", "D": "20 ટકા" }, "correct_answer": "B", "explanation": "Net % change = -30 + 50 + (-30 × 50 / 100) = 20 - 15 = 5% વધારો." }, { "question_number": 71, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક સંખ્યા પહેલા 25% વધે છે અને પછી 25% ઘટે છે. સંખ્યામાં કેટલા ટકા ફેરફાર થશે? (CCE 2023)", "options": { "A": "5% ઘટાડો", "B": "6.25% નો ઘટાડો", "C": "6.25% નો વધારો", "D": "5% વધારો" }, "correct_answer": "B", "explanation": "સમાન ટકા વધારા/ઘટાડા માટે હંમેશાં ઘટાડો = (25² / 100)% = 625 / 100 % = 6.25% ઘટાડો." }, { "question_number": 72, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો વોશિંગ મશીનની કિંમતમાં પહેલા 15% થી ઘટાડો કરવામાં આવે છે અને પછી 20% થી વધારો કરવામાં આવે છે, તો વોશિંગ મશીનની કિંમતમાં ચોખ્ખો ફેરફાર છે: (CCE 2023)", "options": { "A": "2% ઘટાડો", "B": "4% વધારો", "C": "5% ઘટાડો", "D": "2% વધારો" }, "correct_answer": "D", "explanation": "Net % = -15 + 20 + (-15 × 20 / 100) = 5 - 3 = 2% વધારો." }, { "question_number": 73, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જેકબના પગારમાં 10%નો વધારો થયો છે. પછી તેમાં વધુ 10% નો ઘટાડો થાય છે. તો તેના પગારમાં થતો ફેરફાર કેટલો છે? (CCE 2023)", "options": { "A": "10% નો ઘટાડો", "B": "1% નો ઘટાડો", "C": "2% નો વધારો", "D": "10% નો વધારો" }, "correct_answer": "B", "explanation": "Net % = (10² / 100)% = 1% નો ઘટાડો." }, { "question_number": 74, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો શેરનું મૂલ્ય પહેલા 30% વધ્યું અને પછી 40% ઘટ્યું હોત, તો તેના મૂલ્યમાં એકંદર ટકાવારી ફેરફાર શોધો. (CCE 2023)", "options": { "A": "18% ઘટાડો", "B": "12% ઘટાડો", "C": "22% ઘટાડો", "D": "10% ઘટાડો" }, "correct_answer": "C", "explanation": "Net % = +30 - 40 + (30 × -40 / 100) = -10 - 12 = -22% (22% ઘટાડો)." }, { "question_number": 75, "source": "ટકાવારી Lecture 2.pdf", "question_text": "નિલેશે કટલરીની કિંમતમાં 30%નો વધારો કર્યો અને પછી કિંમતમાં 45%નો ઘટાડો કર્યો, કટલરીની કિંમતમાં ચોખ્ખો ફેરફાર આ પ્રમાણે છે: (CCE 2023)", "options": { "A": "28.5% ઘટાડો", "B": "28.5% વધારો", "C": "24.8% ઘટાડો", "D": "26.4% વધારો" }, "correct_answer": "A", "explanation": "Net % = +30 - 45 + (30 × -45 / 100) = -15 - 13.5 = -28.5% (28.5% ઘટાડો)." }, { "question_number": 76, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક નોટબુકની કિંમતમાં 20 ટકાનો ઘટાડો કરવાથી તેનું વેચાણ 25 ટકા વધી જાય છે. તેની આવકની ટકાવારીમાં કેટલો ફેરફાર થશે? (CCE 2023)", "options": { "A": "0 ટકા", "B": "5 ટકાનો ઘટાડો", "C": "2 ટકાનો વધારો", "D": "5 ટકાનો વધારો" }, "correct_answer": "A", "explanation": "Net % = -20 + 25 + (-20 × 25 / 100) = 5 - 5 = 0% ફેરફાર." }, { "question_number": 77, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો એક શેરની કિંમત જાન્યુઆરીમાં 15% વધે છે અને પછી ફેબ્રુઆરીમાં 10% ઘટે છે. જો શેરની અંતિમ કિંમત ₹99 છે, તો જાન્યુઆરીમાં વધારો થયો તે પહેલાં તેની મૂળ કિંમત કેટલી હતી? (CCE 2023)", "options": { "A": "₹90.45", "B": "₹97.45", "C": "₹96.45", "D": "₹95.65" }, "correct_answer": "D", "explanation": "x × (115 / 100) × (90 / 100) = 99 ⇒ x × (1.035) = 99 ⇒ x = 99 / 1.035 ≈ 95.65." }, { "question_number": 78, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જો કોઈ કંપનીના શેરની કિંમત એક દિવસ 10%થી ઘટી જાય અને પછી બીજા દિવસે 20%થી વધે, તો પ્રારંભિક કિંમતમાં ચોખ્ખી ટકાવારીમાં કેટલો ફેરફાર થયો છે? (CCE 2023)", "options": { "A": "10% વધારો", "B": "10% ઘટાડો", "C": "8% વધારો", "D": "8% ઘટાડો" }, "correct_answer": "C", "explanation": "Net % = -10 + 20 + (-10 × 20 / 100) = 10 - 2 = 8% વધારો." }, { "question_number": 79, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક વ્યક્તિ તેની આવકના 25% ભાડા પર ખર્ચે છે અને બાકીની રકમના 15% બચાવે છે. જો તે દર મહિને ₹600 બચાવે છે, તો તેની કુલ માસિક આવક કેટલી છે? (CCE 2023)", "options": { "A": "₹5,400", "B": "₹5,000", "C": "₹5,333", "D": "₹5,200" }, "correct_answer": "C", "explanation": "બાકી આવક = 75%. બચત = 75% ના 15% = 11.25%. 11.25% = 600 ⇒ માસિક આવક = 600 / 0.1125 = 16000 / 3 ≈ ₹5,333." }, { "question_number": 80, "source": "ટકાવારી Lecture 2.pdf", "question_text": "સ્માર્ટફોનની કિંમત પહેલા મહિનામાં 15% વધે છે અને પછી બીજા મહિનામાં 10% ઘટી જાય છે. જો સ્માર્ટફોનની મૂળ કિંમત ₹ 20000 છે, તો બીજા મહિનાના અંતે સ્માર્ટફોનની કિંમત કેટલી હશે? (CCE 2023)", "options": { "A": "₹ 19800", "B": "₹ 20700", "C": "₹ 19400", "D": "₹ 20200" }, "correct_answer": "B", "explanation": "અંતિમ કિંમત = 20000 × 1.15 × 0.90 = 230 × 90 = ₹20,700." }, { "question_number": 81, "source": "ટકાવારી Lecture 2.pdf", "question_text": "A નો પગાર 15% વધ્યો છે અને પછી 10% ઘટ્યો છે. જો અંતિમ પગાર ₹ 20,700 છે, તો મૂળ પગાર કેટલો હતો? (CCE 2023)", "options": { "A": "₹21000", "B": "₹18000", "C": "₹25000", "D": "₹20000" }, "correct_answer": "D", "explanation": "x × 1.15 × 0.90 = 20700 ⇒ x × 1.035 = 20700 ⇒ x = 20000." }, { "question_number": 82, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક મેન્યુફેક્ચરિંગ કંપનીએ ગયા વર્ષની સરખામણીમાં આ વર્ષે ઉત્પાદન ખર્ચમાં 15%નો વધારો નોંધ્યો છે. આનો સામનો કરવા માટે, તેઓ કાર્યક્ષમતામાં સુધારાઓ અમલમાં મૂકે છે જે નવા ખર્ચમાં 10% ઘટાડો કરે તેવી અપેક્ષા છે. જો પ્રારંભિક ઉત્પાદન ખર્ચ ₹20,000 હતો, તો ગોઠવણો પછી કેટલો ખર્ચ થશે? (CCE 2023)", "options": { "A": "₹17,600", "B": "₹20,700", "C": "₹19,800", "D": "₹18,900" }, "correct_answer": "B", "explanation": "ગોઠવણ પછી ખર્ચ = 20000 × 1.15 × 0.90 = ₹20,700." }, { "question_number": 83, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક શેરની કિંમત પહેલા મહિનામાં 10% વધે છે અને પછી બીજા મહિનામાં 5% ઘટે છે. જો શેરની મૂળ કિંમત ₹100 છે, તો બીજા મહિનાના અંતે શેરની કિંમત કેટલી છે? (CCE 2023)", "options": { "A": "₹104.50", "B": "₹105.00", "C": "₹ 95.00", "D": "₹ 104.75" }, "correct_answer": "D", "explanation": "કિંમત = 100 × 1.10 × 0.95 = 104.50." }, { "question_number": 84, "source": "ટકાવારી Lecture 2.pdf", "question_text": "Z1એ Z2 કરતાં 60 ટકા વધુ છે અને Z2 એ Z3 કરતાં 20 ટકા ઓછું છે. જો Z1 એ 640 હોય, તો Z3 ની કિંમત કેટલી છે? (CCE 2023)", "options": { "A": "500", "B": "510", "C": "520", "D": "530" }, "correct_answer": "A", "explanation": "ધારો કે Z3 = 100, Z2 = 80, Z1 = 80 × 1.60 = 128. 128 ભાગ = 640 ⇒ 1 ભાગ = 5. Z3 (100 ભાગ) = 500." }, { "question_number": 85, "source": "ટકાવારી Lecture 2.pdf", "question_text": "નમનની આવક ચમનની આવક કરતાં 50 ટકા વધુ છે. ચમનની આવક વિમલની આવક કરતાં 25 ટકા વધુ છે અને વિમલની આવક નીતિનની આવક કરતાં 20 ટકા ઓછી છે. જો નીતિનની આવક Rs. 16000 છે, તો નમનની આવક કેટલી હશે? (CCE 2023)", "options": { "A": "Rs. 20000", "B": "Rs. 22000", "C": "Rs. 25000", "D": "Rs. 24000" }, "correct_answer": "D", "explanation": "નીતિન = 16000. વિમલ = 16000 × 0.80 = 12800. ચમન = 12800 × 1.25 = 16000. નમન = 16000 × 1.50 = 24000." }, { "question_number": 86, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક ડીશ વોશરનું મૂલ્ય દર વર્ષે 10% ના દરે ઘટે છે. જો તેની હાલની કિંમત ₹ 3645 છે, તો ત્રણ વર્ષ પહેલા તે ડીશ વોશરની કિંમત કેટલી હતી? (CCE 2023)", "options": { "A": "₹6300", "B": "₹4200", "C": "₹5000", "D": "₹5500" }, "correct_answer": "C", "explanation": "x × (0.9)³ = 3645 ⇒ x × 0.729 = 3645 ⇒ x = 5000." }, { "question_number": 87, "source": "ટકાવારી Lecture 2.pdf", "question_text": "ફ્લાવર પોટની કિંમતમાં ક્રમિક રીતે 25% 32% અને 40%નો વધારો થાય છે. ટકાવારીમાં થયેલો ચોખ્ખો વધારો શોધો. (CCE 2023)", "options": { "A": "131%", "B": "134%", "C": "132%", "D": "133%" }, "correct_answer": "A", "explanation": "100 × 1.25 × 1.32 × 1.40 = 231. ચોખ્ખો વધારો = 231 - 100 = 131%." }, { "question_number": 88, "source": "ટકાવારી Lecture 2.pdf", "question_text": "વિક્રમની આવક વિકાંતની આવક કરતાં 30 ટકા વધુ છે. વિકાંતની આવક વિનયની આવક કરતાં 25 ટકા વધુ છે અને વિનયની આવક વિજયની આવક કરતાં 40 ટકા ઓછી છે. જો વિજયની આવક Rs. 48000 હોય, તો વિક્રમની આવક કેટલી હશે? (CCE 2023)", "options": { "A": "Rs. 48600", "B": "Rs. 48000", "C": "Rs. 46800", "D": "Rs. 47000" }, "correct_answer": "A", "explanation": "વિજય = 48000. વિનય = 48000 × 0.60 = 28800. વિકાંત = 28800 × 1.25 = 36000. વિક્રમ = 36000 × 1.30 = 46800." }, { "question_number": 89, "source": "ટકાવારી Lecture 2.pdf", "question_text": "નિખિલને વિનિત કરતા 30 ટકા ઓછા ગુણ મળ્યા છે. રણજિતને વિનિત કરતા 20 ટકા ઓછા ગુણ મળ્યા છે. જો રણજિતને 200 ગુણ મળ્યા હોય, તો નિખિલના ગુણ કેટલા છે? (CCE 2023)", "options": { "A": "150", "B": "175", "C": "145", "D": "125" }, "correct_answer": "B", "explanation": "રણજિત (80% વિનિતના) = 200 ⇒ વિનિતના ગુણ = 250. નિખિલના ગુણ (70% વિનિતના) = 250 ના 70% = 175." }, { "question_number": 90, "source": "ટકાવારી Lecture 2.pdf", "question_text": "કારનું મૂલ્ય તેના પ્રથમ વર્ષમાં 20% ઘટે છે અને બીજા વર્ષમાં 10% વધે છે. જો કારની શરૂઆતમાં કિંમત ₹150000 હોય, તો બીજા વર્ષના અંતે તેની કિંમત (₹માં) કેટલી હશે? (CCE 2023)", "options": { "A": "150000", "B": "140400", "C": "132000", "D": "126000" }, "correct_answer": "C", "explanation": "અંતિમ કિંમત = 150000 × 0.80 × 1.10 = 120000 × 1.10 = ₹1,32,000." }, { "question_number": 91, "source": "ટકાવારી Lecture 2.pdf", "question_text": "30% નો એક એવા બે ક્રમિક વધારા 40% નો એક એવા બે ક્રમિક ઘટાડા કરતા લગભગ કેટલા ટકા વધારે છે? (CCE 2023)", "options": { "A": "7.8%", "B": "7.9%", "C": "7.7%", "D": "7.6%" }, "correct_answer": "A", "explanation": "30% ના બે વધારા = +30 + 30 + 9 = +69%. 40% ના બે ઘટાડા = -40 - 40 + 16 = -64% (મૂલ્ય 36%). તફાવત = 69% - 64% = 5%. ટકાવારી વધારે = (5 / 64) × 100 ≈ 7.8%." }, { "question_number": 92, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક કલાકાર તેના 40,000 ના બજેટમાંથી 25% સામગ્રી પર ખર્ચ કરે છે. જો તેણીનું બજેટ આવતા વર્ષે 50% વધે છે અને તે સમાન ટકાવારી સામગ્રી પર ખર્ચ કરતી હોય, તો તે આવતા વર્ષે સામગ્રી પર કેટલો ખર્ચ કરશે? (CCE 2023)", "options": { "A": "₹ 15,000", "B": "₹ 12,000", "C": "₹ 18,000", "D": "₹ 10,000" }, "correct_answer": "A", "explanation": "નવું બજેટ = 40000 × 1.50 = 60000. સામગ્રી ખર્ચ = 60000 ના 25% = ₹15,000." }, { "question_number": 93, "source": "ટકાવારી Lecture 2.pdf", "question_text": "રાજુએ એક પરીક્ષામાં 35 ટકા માર્ક્સ મેળવ્યા હતા અને 20 માર્ક્સથી નાપાસ થયો હતો. જો તે 55 ટકા ગુણ મેળવે, તો તેને પાસિંગ માર્ક્સ કરતા 20 ગુણ વધુ મળે એમ છે. પરીક્ષા માટે પાસિંગ માર્ક્સ કેટલા હોવા જોઈએ? (CCE 2023)", "options": { "A": "80", "B": "90", "C": "70", "D": "100" }, "correct_answer": "B", "explanation": "તફાવત (55% - 35%) = 20% = 40 ગુણ ⇒ 1% = 2 ગુણ. 35% = 70 ગુણ. પાસિંગ માર્ક્સ = 70 + 20 = 90." }, { "question_number": 94, "source": "ટકાવારી Lecture 2.pdf", "question_text": "લોકેશની આવક અને ખર્ચનો સંબંધિત ગુણોત્તર 4 : 3 છે, જો તેની આવકમાં 75 ટકાનો વધારો થાય અને તેના ખર્ચમાં 75 ટકાનો ઘટાડો થાય, તો તેની આવક અને ખર્ચનો નવો સંબંધિત ગુણોત્તર શું હશે? (CCE 2023)", "options": { "A": "28:3", "B": "28:2", "C": "28:1", "D": "27:1" }, "correct_answer": "A", "explanation": "નવી આવક = 4 × 1.75 = 7. નવો ખર્ચ = 3 × 0.25 = 0.75. ગુણોત્તર = 7 : 0.75 = 700 : 75 = 28 : 3." }, { "question_number": 95, "source": "ટકાવારી Lecture 2.pdf", "question_text": "રાહુલની આવક અને ખર્ચનો પ્રારંભિક ગુણોત્તર અનુક્રમે 9 : 4 હતો. તેની આવક 20 ટકા વધે છે અને ખર્ચ 25 ટકા વધે છે. જો તેની બચત Rs. 58000 હોય, તો રાહુલની પ્રારંભિક આવક કેટલી હતી? (CCE 2023)", "options": { "A": "₹100000", "B": "₹80000", "C": "₹90000", "D": "₹70000" }, "correct_answer": "C", "explanation": "ધારો કે આવક = 900, ખર્ચ = 400. નવી આવક = 1080, નવો ખર્ચ = 500. નવી બચત = 580. 580 ભાગ = 58000 ⇒ 1 ભાગ = 100. પ્રારંભિક આવક (900 ભાગ) = 90000." }, { "question_number": 96, "source": "ટકાવારી Lecture 2.pdf", "question_text": "શાળાની ચૂંટણીમાં, 10% મત અમાન્ય હતા. એક ઉમેદવારે 70% માન્ય મતો જીતીને પ્રતિસ્પર્ધીને 180 મતોથી હરાવ્યા. ચૂંટણીમાં કુલ કેટલા મત પડ્યા? (CCE 2023)", "options": { "A": "400 મત", "B": "500 મત", "C": "900 મત", "D": "600 મત" }, "correct_answer": "B", "explanation": "ધારો કે કુલ મત = 100, માન્ય મત = 90. વિજેતા = 63, હારેલ = 27. તફાવત = 36. 36 ભાગ = 180 ⇒ 1 ભાગ = 5. કુલ મત = 500." }, { "question_number": 97, "source": "ટકાવારી Lecture 2.pdf", "question_text": "A અને B ચૂંટણીમાં ભાગ લે છે. પડેલા તમામ મત માન્ય છે અને આ બે ઉમેદવારોમાંથી કોઈ એકની તરફણમાં છે. જો A ને 55% મત મળે અને 100 મતોથી જીતે, તો B ને મળેલા મતો શોધો. (CCE 2023)", "options": { "A": "550", "B": "650", "C": "750", "D": "450" }, "correct_answer": "D", "explanation": "A = 55%, B = 45%. જીતનું માર્જિન = 10% = 100 ⇒ 1% = 10. B ના મત (45%) = 450." }, { "question_number": 98, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં 20% મતો અમાન્ય જાહેર કરવામાં આવ્યા. જો વિજેતા માન્ય મતોના 60% મેળવે અને 4000 મતો થી જીતે. તો કુલ મતોની સંખ્યા શોધો. (CCE 2023)", "options": { "A": "25000", "B": "22000", "C": "30000", "D": "20000" }, "correct_answer": "A", "explanation": "x × (80/100) × (20/100) = 4000 ⇒ x × 0.16 = 4000 ⇒ x = 25000." }, { "question_number": 99, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બે ઉમેદવારો A અને B વચ્ચેની સામાન્ય ચૂંટણીમાં, ભૂલોને કારણે 10% મતો કાઢી નાખવામાં આવે છે, અને ઉમેદવાર A ને માન્ય મતોના 65% મળે છે. જો ઉમેદવાર A 405 મતોના ગાાળા (માર્જિન) થી જીતે છે, તો કુલ કેટલા મત આપવામાં આવ્યા હતા? (CCE 2023)", "options": { "A": "2000 મત", "B": "2200 મત", "C": "2000 મત", "D": "1500 મત" }, "correct_answer": "D", "explanation": "x × (90/100) × (30/100) = 405 ⇒ x × 0.27 = 405 ⇒ x = 1500." }, { "question_number": 100, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બે ઉમેદવારો વચ્ચે થયેલ ચૂંટણી માં એકને કુલ મતમાંથી 40% માન્ય મત મળ્યા, 20% મત ગેરમાન્ય હતા. જો કુલ મળીને 5200 મતદાન થયુ હોય, તો અન્ય ઉમેદવારને કેટલા માન્ય મત મળ્યા હતા? (CCE 2023)", "options": { "A": "3090", "B": "2260", "C": "3541", "D": "2496" }, "correct_answer": "D", "explanation": "માન્ય મત = 5200 ના 80% = 4160. અન્ય ઉમેદવારને માન્ય મતોના 60% મળ્યા = 4160 ના 60% = 2496." }, { "question_number": 101, "source": "ટકાવારી Lecture 2.pdf", "question_text": "જ્હોનની માસિક આવક 20% વધે છે. અને તેનો માસિક ખર્ચ પણ 25% વધે છે. જો વધારો થયો તે પહેલા જ્હોનની બચત $600 હતી અને વધારો થયા પછી તેની બચત બદલાતી નથી. તો વધારા પહેલા જ્હોનની માસિક આવક કેટલી હતી? (CCE 2023)", "options": { "A": "$2,400", "B": "$3,000", "C": "$3,600", "D": "$6,000" }, "correct_answer": "B", "explanation": "આવક વધારો = ખર્ચ વધારો. 20% આવક = 25% ખર્ચ ⇒ આવક/ખર્ચ = 5/4. બચત = 1 ભાગ = 600. આવક (5 ભાગ) = 3000." }, { "question_number": 102, "source": "ટકાવારી Lecture 2.pdf", "question_text": "દિપેશ તેની આવકમાંથી 24% બચાવે છે. જો તેની આવકમાં 38% નો વધારો થયો અને હજુ પણ એટલી જ રકમ બચાવે છે. તેના ખર્ચમાં ટકાવારીનો વધારો શોધો. (CCE 2023)", "options": { "A": "50%", "B": "48%", "C": "33%", "D": "26%" }, "correct_answer": "A", "explanation": "ધારો કે મૂળ આવક = 100, બચત = 24, ખર્ચ = 76. નવી આવક = 138, નવી બચત = 24, નવો ખર્ચ = 114. ખર્ચ વધારો = 114 - 76 = 38. ટકાવારી વધારો = (38 / 76) × 100 = 50%." }, { "question_number": 103, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં 12% મતદારોએ મતદાન નહોતું કર્યું, જ્યારે 16% મત અમાન્ય જાહેર થયા હતા. જો વિજેતાને 60% મત મળ્યા હોય અને 14784 મતોથી જીત્યા હોય, તો કુલ કેટલા મતદારોએ પોતાનો મત આપ્યો છે તે શોધો? (CCE 2023)", "options": { "A": "88000", "B": "88100", "C": "89100", "D": "89000" }, "correct_answer": "A", "explanation": "ગણતરી: 88000 કુલ મતદારો, પડેલા મત = 88000 × 0.88 = 77440." }, { "question_number": 104, "source": "ટકાવારી Lecture 2.pdf", "question_text": "મેયરના પદ માટે બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં, ભૂલોને કારણે 10% મતો રદ કરવામાં આવે છે, અને ઉમેદવાર P માન્ય મતોના 60% મત મેળવે છે. જો ઉમેદવાર P એ 270 મતોના માર્જિનથી જીતે છે, તો કુલ કેટલા મત આપવામાં આવ્યા હતા? (CCE 2023)", "options": { "A": "2400 મત", "B": "2000 મત", "C": "2800 મત", "D": "1500 મત" }, "correct_answer": "D", "explanation": "x × (90/100) × (20/100) = 270 ⇒ x × 0.18 = 270 ⇒ x = 1500." }, { "question_number": 105, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની એક ચૂંટણીમાં 25% મતદારોએ તેમના મત આપ્યા જેમાંંથી 10% મત અમાન્ય જાહેર થયા. એક ઉમેદવારને 7290 મત મળ્યા જે કુલ માન્ય મતોના 25% હતા. તે ચૂંટણીમાં નોંધાયેલા મતોની કુલ સંખ્યા શોધો. (CCE 2023)", "options": { "A": "129600", "B": "100000", "C": "154689", "D": "186800" }, "correct_answer": "A", "explanation": "x × (25/100) × (90/100) × (25/100) = 7290 ⇒ x × (81 / 1600) = 7290 ⇒ x = 129600." }, { "question_number": 106, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બે ઉમેદવારો વચ્ચે મેયરની ચૂંટણીમાં નોંધાયેલા મતદારોમાંથી 20% મતદારોએ મતદાન કરવાનું ટાળ્યું હતું. વિજેતા ઉમેદવારને કુલ પડેલા મતોના 60% મત મળ્યા, 240 મતોના ગાાળા (માર્જિન) થી જીતી ગયા. નોંધાયેલા મતદારોની કુલ સંખ્યા કેટલી છે? (CCE 2023)", "options": { "A": "2000", "B": "1600", "C": "1200", "D": "1500" }, "correct_answer": "D", "explanation": "ધારો કે નોંધાયેલા મત = 100, પડેલા મત = 80. વિજેતા = 80 ના 60% = 48, હારેલ = 32. તફાવત = 16. 16 ભાગ = 240 ⇒ 1 ભાગ = 15. નોંધાયેલા મત (100 ભાગ) = 1500." }, { "question_number": 107, "source": "ટકાવારી Lecture 2.pdf", "question_text": "એક ચૂંટણીમાં બે ઉમેદવારો હોય છે. જો 20% મત અમાન્ય હોય અને વિજેતા કુલ મતોના 60% મેળવે અને 400 મતોથી જીતે તો કુલ મતો શોધો. (CCE 2023)", "options": { "A": "2000", "B": "3000", "C": "4000", "D": "1000" }, "correct_answer": "A", "explanation": "કુલ મત = 100, વિજેતા = 60, અમાન્ય = 20, હારેલ = 20. તફાવત = 40. 40% = 400 ⇒ 100% = 2000." }, { "question_number": 108, "source": "ટકાવારી Lecture 2.pdf", "question_text": "બે ઉમેદવારો વચ્ચેની ચૂંટણીમાં, 17% મતો અમાન્ય હતા. વિજેતાને માન્ય મતોના 60% મળે છે અને તે 16600 મતોથી જીતે છે. માન્ય મતોની કુલ રાખ્યા શોધો. (CCE 2023)", "options": { "A": "97000", "B": "17,00,000", "C": "83000", "D": "1,00,000" }, "correct_answer": "C", "explanation": "માન્ય મતોના જીતનું માર્જિન = 60% - 40% = 20%. 20% = 16600 ⇒ માન્ય મતોની કુલ સંખ્યા (100%) = 16600 × 5 = 83,000." } ] };
  
  const percentageQuestions = percentageSourceData.questions.map(q => ({
    t: "Percentage",
    q: q.question_text,
    o: [q.options.A, q.options.B, q.options.C, q.options.D],
    a: ["A", "B", "C", "D"].indexOf(q.correct_answer),
    y: q.source,
    e: q.explanation,
    sv: q.explanation.split(/[\n.]+/).flatMap(line => line.split(/\s*⟹\s*/).map(x => x.trim()).filter(Boolean))
  }));

  const partnershipSourceData = {"subject":"Quantitative Aptitude / Mathematics","topic_name":"ભાગીદારી (Partnership - 100% Complete)","source_file":"ભાગીદારી .pdf","total_questions_count":33,"concept_notes":{"definition":"જ્યારે બે કે તેથી વધુ વ્યક્તિઓ અમુક મૂડીનું કોઈ ચોક્કસ સમય માટે રોકાણ કરીને વેપાર કે ધંધાની શરૂઆત કરે, તો તેને ભાગીદારી (Partnership) કહેવાય છે. ભાગીદારીમાં જોડાયેલ વ્યક્તિઓને ભાગીદારો (Partners) કહેવાય છે.","fundamental_rule":"નફો ∝ રોકાણ (મૂડી) × સમય (Profit ∝ Investment × Time). એટલે કે, નફાનો ગુણોત્તર = (મૂડીનો ગુણોત્તર) × (સમયનો ગુણોત્તર).","types_of_partnership":[{"type":"સાદી ભાગીદારી (Simple Partnership)","description":"જ્યારે તમામ ભાગીદારોનું મૂડી રોકાણ સમાન હોય અથવા તમામ ભાગીદારોનો સમયગાળો અચળ (સમાન) હોય.","rules":["જો સમય અચળ હોય, તો નફો ∝ રોકાણ (Profit Ratio = Investment Ratio). એટલે કે A:B રોકાણ x:y હોય, તો નફો = x:y.","જો રોકાણ અચળ હોય, તો નફો ∝ સમય (Profit Ratio = Time Ratio). એટલે કે A:B સમય t1:t2 હોય, તો નફો = t1:t2."]},{"type":"મિશ્ર ભાગીદારી (Compound Partnership)","description":"જ્યારે ભાગીદારોનું મૂડી રોકાણ અને સમયગાળો બંને અલગ-અલગ હોય.","rules":["નફાનો ગુણોત્તર = (રોકાણ1 × સમય1) : (રોકાણ2 × સમય2) : (રોકાણ3 × સમય3)","જો A અને B ના રોકાણ x અને y હોય, અને સમયગાળો t1 અને t2 હોય, તો નફાનો ગુણોત્તર A:B = (x × t1) : (y × t2).","સમયગાળાનો ગુણોત્તર = (નફાનો ગુણોત્તર) / (રોકાણનો ગુણોત્તર)","રોકાણનો ગુણોત્તર = (નફાનો ગુણોત્તર) / (સમયગાળાનો ગુણોત્તર)"]}],"important_shortcut_tricks":["વચ્ચેથી નાણાં ઉમેરવા કે ઉપાડવા: (પ્રારંભિક મૂડી × પ્રથમ સમય) + (નવી મૂડી × બાકીનો સમય).","ભાગીદારીમાં જોડાયાનો સમય vs રોકેલો સમય: જો B ધંધામાં x મહિના પછી જોડાય છે, તો તેનો રોકેલો સમય = (12 - x) મહિના લેવો.","સરખામણી પદ્ધતિ: જો કુલ ગુણોત્તર N પદ હોય અને રકમ R હોય, તો 1 ભાગ = R / N, જેનાથી દરેકનો હિસ્સો ડાયરેક્ટ શોધી શકાય."]},"questions":[{"question_number":1,"source":"ભાગીદારી .pdf (Page 6)","topic":"સાદી ભાગીદારી - નફાનો ગુણોત્તર","question_text":"A અને B અનુક્રમે ₹ 4000 અને ₹ 12000 રોકીને ધંધાની શરૂઆત કરે છે તો એક વર્ષ પછી તેને થતાં નફા નો ગુણોત્તર શોધો.","options":{"A":"3:1","B":"1:3","C":"1:2","D":"2:1"},"correct_answer":"B","explanation":"અહીં સમય અચળ (1 વર્ષ) છે, તેથી નફાનો ગુણોત્તર = રોકાણનો ગુણોત્તર.\nનફાનો ગુણોત્તર A : B = 4000 : 12000 = 4 : 12 = 1 : 3.\nસાચો જવાબ: (B) 1:3."},{"question_number":2,"source":"ભાગીદારી .pdf (Page 7)","topic":"રોકાણના ગણા સંબંધથી નફાની વહેંચણી","question_text":"A અને B ભાગીદારીમાં એક ધંધો શરૂ કરે છે, A દ્વારા કરવામાં આવેલું રોકાણ B દ્વારા કરવામાં આવેલા રોકાણના ત્રણ ગણા જેટલું છે, જો એક વર્ષ પછી કુલ નફો ₹ 52000 થતો હોય તો A ને થતો નફો શોધો.","options":{"A":"₹ 13000","B":"₹ 33000","C":"₹ 36000","D":"₹ 39000"},"correct_answer":"D","explanation":"ધારો કે B નું રોકાણ = 1, તો A નું રોકાણ = 3.\nતેથી નફાનો ગુણોત્તર A : B = 3 : 1.\nકુલ ભાગ = 3 + 1 = 4 ભાગ.\n4 ભાગ = ₹ 52,000 => 1 ભાગ = ₹ 13,000.\nA નો નફો (3 ભાગ) = 3 × 13,000 = ₹ 39,000.\nસાચો જવાબ: (D) ₹ 39000."},{"question_number":3,"source":"ભાગીદારી .pdf (Page 8)","topic":"સમાન સમય માટે નફાની વહેંચણી","question_text":"A અને B અનુક્રમે ₹ 24000 અને ₹ 8000 રોકાણ કરીને એક ધંધાની શરૂઆત કરે છે જો 2 વર્ષ પછી થતો કુલ નફો ₹ 48000 હોય તો B ને થતો નફો શોધો.","options":{"A":"₹ 8000","B":"₹ 12000","C":"₹ 36000","D":"₹ 24000"},"correct_answer":"B","explanation":"અહીં સમય 2 વર્ષ સમાન છે.\nરોકાણનો ગુણોત્તર A : B = 24000 : 8000 = 3 : 1.\nકુલ ભાગ = 3 + 1 = 4 ભાગ.\n4 ભાગ = ₹ 48,000 => 1 ભાગ = ₹ 12,000.\nB નો નફો (1 ભાગ) = ₹ 12,000.\nસાચો જવાબ: (B) ₹ 12000."},{"question_number":4,"source":"ભાગીદારી .pdf (Page 9)","topic":"અલગ-અલગ સમય માટે નફાનો ગુણોત્તર","question_text":"A, B અને C ત્રણેય ₹ 50,000 નું રોકાણ કરીને એક ધંધાની શરૂઆત કરે છે તેઓ અનુક્રમે 9 મહિના, 6 મહિના અને 12 મહિના ભાગીદારીમાં રહે છે તો તેના નફાનો ગુણોત્તર શોધો.","options":{"A":"2:3:4","B":"2:4:3","C":"3:2:4","D":"3:4:2"},"correct_answer":"C","explanation":"અહીં ત્રણેયનું રોકાણ ₹ 50,000 સમાન છે.\nતેથી નફાનો ગુણોત્તર = સમયનો ગુણોત્તર.\nનફાનો ગુણોત્તર A : B : C = 9 : 6 : 12 = 3 : 2 : 4 (3 વડે ભાગતાં).\nસાચો જવાબ: (C) 3:2:4."},{"question_number":5,"source":"ભાગીદારી .pdf (Page 10, CCE 2023)","topic":"CCE 2023 - ગુણોત્તર પરથી કુલ રોકાણ અને નફાની વહેંચણી","question_text":"એક વ્યવસાયિક નવઉધમમાં, ભાગીદારો A, B, અને C 3:4:5 ના ગુણોત્તરમાં રોકાણ કરે છે. જો ભાગીદાર A ₹9,000 નું રોકાણ કરે છે, તો બધા ભાગીદારો દ્વારા કુલ રોકાણ કેટલું છે અને જો વ્યવસાયમાં ₹10,000 નફો થાય છે, તો તેમાં B નો હિસ્સો કેટલો હશે?","options":{"A":"₹ 48,000 અને B નો હિસ્સો ₹ 4547","B":"₹ 40,000 અને B નો હિસ્સો ₹ 3567","C":"₹ 30,000 અને B નો હિસ્સો ₹ 4567","D":"₹ 36,000 અને B નો હિસ્સો ₹ 3333"},"correct_answer":"D","explanation":"રોકાણનો ગુણોત્તર A : B : C = 3 : 4 : 5.\nA નું રોકાણ = 3 ભાગ = ₹ 9,000 => 1 ભાગ = ₹ 3,000.\nકુલ રોકાણ (3 + 4 + 5 = 12 ભાગ) = 12 × 3,000 = ₹ 36,000.\nનફો = ₹ 10,000 માં B નો હિસ્સો (4/12 = 1/3 ભાગ) = 10,000 / 3 = ₹ 3333.33 (અંદાજે ₹ 3333).\nસાચો જવાબ: (D) ₹ 36,000 અને B નો હિસ્સો ₹ 3333."},{"question_number":6,"source":"ભાગીદારી .pdf (Page 11, CCE 2023)","topic":"CCE 2023 - ગણા સંબંધથી નફાનો તફાવત","question_text":"I, J, અને K એ એક બિઝનેસ શરૂ કર્યો. I નું રોકાણ J ના રોકાણ કરતાં બે ગણું છે અને J નું રોકાણ K ના રોકાણ કરતાં ત્રણ ગણું છે. જો એક વર્ષ પછીનો વાર્ષિક નફો ₹ 14,000 હોય, તો J અને K ના નફામાં તફાવત શોધો.","options":{"A":"₹ 4200","B":"₹ 1400","C":"₹ 2800","D":"₹ 6400"},"correct_answer":"C","explanation":"ધારો કે K = 1.\nતેથી J = 3 × 1 = 3, અને I = 2 × J = 2 × 3 = 6.\nરોકાણનો ગુણોત્તર I : J : K = 6 : 3 : 1.\nકુલ ભાગ = 6 + 3 + 1 = 10 ભાગ = ₹ 14,000 => 1 ભાગ = ₹ 1,400.\nJ અને K ના નફાનો તફાવત = (3 - 1) = 2 ભાગ = 2 × 1,400 = ₹ 2800.\nસાચો જવાબ: (C) ₹ 2800."},{"question_number":7,"source":"ભાગીદારી .pdf (Page 12, CCE 2023)","topic":"CCE 2023 - પ્રારંભિક મૂડી પરથી નફાના ભાગ","question_text":"બે મિત્રો A અને B એ ₹ 3 લાખ અને ₹ 6 લાખની પ્રારંભિક મૂડીના યોગદાન સાથે ધંધાની શરૂઆત કરી હતી. વર્ષના અંતે ધંધામાં ₹ 24,000નો નફો થયો તો A, B ના નફાનો ભાગ શોધો.","options":{"A":"₹ 16,000, ₹ 8,000","B":"₹ 8,000, ₹ 16,000","C":"₹ 7,000, ₹ 17,000","D":"₹ 6,000, ₹ 18,000"},"correct_answer":"B","explanation":"A : B રોકાણનો ગુણોત્તર = 3 લાખ : 6 લાખ = 1 : 2.\nકુલ ભાગ = 1 + 2 = 3 ભાગ = ₹ 24,000 => 1 ભાગ = ₹ 8,000.\nA નો ભાગ (1 ભાગ) = ₹ 8,000.\nB નો ભાગ (2 ભાગ) = ₹ 16,000.\nસાચો જવાબ: (B) ₹ 8,000, ₹ 16,000."},{"question_number":8,"source":"ભાગીદારી .pdf (Page 13, CCE 2023)","topic":"CCE 2023 - ત્રણ ભાગીદારો વચ્ચે નફાની વહેંચણી","question_text":"ત્રણ ભાગીદારો, P, Q અને R એક પ્રોજેક્ટમાં યોગદાન આપે છે. P નું યોગદાન Rs. 40,000, Q નું યોગદાન Rs. 60,000 અને R નું યોગદાન Rs. 20,000 છે. Rs.24,000 ના નફામાં P નો હિસ્સો કેટલો છે?","options":{"A":"Rs.8,000","B":"Rs.6,000","C":"Rs.10,000","D":"Rs.7,500"},"correct_answer":"A","explanation":"P : Q : R રોકાણનો ગુણોત્તર = 40,000 : 60,000 : 20,000 = 2 : 3 : 1.\nકુલ ભાગ = 2 + 3 + 1 = 6 ભાગ = Rs. 24,000 => 1 ભાગ = Rs. 4,000.\nP નો હિસ્સો (2 ભાગ) = 2 × 4,000 = Rs. 8,000.\nસાચો જવાબ: (A) Rs.8,000."},{"question_number":9,"source":"ભાગીદારી .pdf (Page 14, CCE 2023)","topic":"CCE 2023 - ચાર ભાગીદારોમાં નફાની વહેંચણી","question_text":"ચાર ભાગીદારો A, B, C અને D એક બિઝનેસ શરૂ કરે છે. A $12,000નું રોકાણ કરે છે. B $16,000નું રોકાણ કરે છે. C $24,000નું રોકાણ કરે છે. અને D $28,000નું રોકાણ કરે છે. $40,000ના નફામાં A નો હિસ્સો કેટલો રહેશે?","options":{"A":"$10,000","B":"$12,000","C":"$6,000","D":"$8,000"},"correct_answer":"C","explanation":"A : B : C : D રોકાણનો ગુણોત્તર = 12 : 16 : 24 : 28 = 3 : 4 : 6 : 7.\nકુલ ભાગ = 3 + 4 + 6 + 7 = 20 ભાગ = $40,000 => 1 ભાગ = $2,000.\nA નો હિસ્સો (3 ભાગ) = 3 × 2,000 = $6,000.\nસાચો જવાબ: (C) $6,000."},{"question_number":10,"source":"ભાગીદારી .pdf (Page 15, CCE 2023)","topic":"CCE 2023 - અપૂર્ણ ભાગાકાર વાળા નફાની ગણતરી","question_text":"ત્રણ મિત્રો A, B અને C એક બિઝનેસ શરૂ કરે છે. A ₹6000નું રોકાણ કરે છે, B ₹8000નું રોકાણ કરે છે અને C ₹ 10000નું રોકાણ કરે છે. ₹25,000ના નફામાં Bનો હિસ્સો કેટલો છે?","options":{"A":"₹ 8000","B":"₹ 6250","C":"₹ 8333","D":"₹ 10,400"},"correct_answer":"C","explanation":"A : B : C રોકાણનો ગુણોત્તર = 6 : 8 : 10 = 3 : 4 : 5.\nકુલ ભાગ = 3 + 4 + 5 = 12 ભાગ = ₹ 25,000.\nB નો હિસ્સો (4 ભાગ) = 25,000 × (4 / 12) = 25,000 / 3 = ₹ 8333.33 (અંદાજે ₹ 8333).\nસાચો જવાબ: (C) ₹ 8333."},{"question_number":11,"source":"ભાગીદારી .pdf (Page 16, CCE 2023)","topic":"CCE 2023 - કેફે રોકાણ નફા વહેંચણી","question_text":"ત્રણ ભાગીદારો, એમી, બ્રાયન અને ક્રિસ, નવા કેફેમાં રોકાણ કરે છે. એમી ₹50,000, બ્રાયન ₹ 70,000 અને ક્રિસ ₹ 80,000 નું યોગદાન આપે છે. એક વર્ષ પછી, કાફે ₹60,000 નો નફો કરે છે. જો નફો તેમના રોકાણોના પ્રમાણમાં વહેંચવામાં આવે, તો બ્રાયનને કેટલો નફો મળે છે?","options":{"A":"₹ 24,000","B":"₹ 20,000","C":"₹ 21,000","D":"₹ 15,000"},"correct_answer":"C","explanation":"એમી : બ્રાયન : ક્રિસ ગુણોત્તર = 5 : 7 : 8.\nકુલ ભાગ = 5 + 7 + 8 = 20 ભાગ = ₹ 60,000 => 1 ભાગ = ₹ 3,000.\nબ્રાયનનો નફો (7 ભાગ) = 7 × 3,000 = ₹ 21,000.\nસાચો જવાબ: (C) ₹ 21,000."},{"question_number":12,"source":"ભાગીદારી .pdf (Page 17, CCE 2023)","topic":"CCE 2023 - સરળ નફાની ગણતરી","question_text":"ત્રણ ભાગીદારો, A, B, અને C એક વ્યવસાય શરૂ કરે છે. A એ ₹10,000નું રોકાણ કર્યું છે, B ₹15,000નું રોકાણ કરે છે અને C એ ₹20,000નું રોકાણ કર્યું છે. જો વ્યવસાયમાં ₹27,000 નો નફો થયો હોય, તો નફામાં A નો હિસ્સો કેટલો છે?","options":{"A":"₹ 9,000","B":"₹ 8,000","C":"₹ 7,000","D":"₹ 6,000"},"correct_answer":"D","explanation":"A : B : C રોકાણનો ગુણોત્તર = 10 : 15 : 20 = 2 : 3 : 4.\nકુલ ભાગ = 2 + 3 + 4 = 9 ભાગ = ₹ 27,000 => 1 ભાગ = ₹ 3,000.\nA નો હિસ્સો (2 ભાગ) = 2 × 3,000 = ₹ 6,000.\nસાચો જવાબ: (D) ₹ 6,000."},{"question_number":13,"source":"ભાગીદારી .pdf (Page 18, CCE 2023)","topic":"CCE 2023 - 4 ભાગીદારોમાં ચોથા નો હિસ્સો","question_text":"ચાર ભાગીદારો, A, B, C અને D, એક બિઝનેસમાં રોકાણ કરે છે. A એ Rs. 25,000નું રોકાણ કરે છે, B એ Rs. 35,000નું રોકાણ કરે છે, C એ Rs. 40,000નું રોકાણ કરે છે અને D એ Rs. 50,000નું રોકાણ કરે છે. તો Rs. 30,000 ના નફામાં D નો હિસ્સો(ભાગ) કેટલો છે?","options":{"A":"Rs.8,000","B":"Rs.9,000","C":"Rs. 10,000","D":"Rs.7,000"},"correct_answer":"C","explanation":"A : B : C : D ગુણોત્તર = 25 : 35 : 40 : 50 = 5 : 7 : 8 : 10.\nકુલ ભાગ = 5 + 7 + 8 + 10 = 30 ભાગ = Rs. 30,000 => 1 ભાગ = Rs. 1,000.\nD નો હિસ્સો (10 ભાગ) = 10 × 1,000 = Rs. 10,000.\nસાચો જવાબ: (C) Rs. 10,000."},{"question_number":14,"source":"ભાગીદારી .pdf (Page 19, CCE 2023)","topic":"CCE 2023 - નફાનો તફાવત (સરખામણી)","question_text":"ત્રણ મિત્રો એમ્મા, નોહ અને ઓલિવિયા સંયુક્ત ઉધમમાં રોકાણ કરે છે. એમ્મા ₹6,000નું રોકાણ કરે છે, નોહ ₹8,000નું રોકાણ કરે છે અને ઓલિવિયા ₹10,000નું રોકાણ કરે છે, જો તેઓ તેમના રોકાણના પ્રમાણમાં નફો વહેંચવા માટે સંમત થાય અને કુલ નફો ₹9,600 હોય તો ઓલિવિયાને એમ્માની સરખામણીમાં કેટલી વધુ રકમ મળશે?","options":{"A":"₹ 2,400","B":"₹ 4,000","C":"₹ 1,600","D":"₹ 3,200"},"correct_answer":"C","explanation":"એમ્મા (A) : નોહ (N) : ઓલિવિયા (O) ગુણોત્તર = 6 : 8 : 10 = 3 : 4 : 5.\nકુલ ભાગ = 3 + 4 + 5 = 12 ભાગ = ₹ 9,600 => 1 ભાગ = ₹ 800.\nઓલિવિયા અને એમ્મા વચ્ચે તફાવત = (5 - 3) = 2 ભાગ = 2 × 800 = ₹ 1,600.\nસાચો જવાબ: (C) ₹ 1,600."},{"question_number":15,"source":"ભાગીદારી .pdf (Page 20, CCE 2023)","topic":"CCE 2023 - 4 રોકાણકારોમાં ત્રીજા નો હિસ્સો","question_text":"ચાર રોકાણકારો, P, Q, R, અને S, સંયુક્ત વ્યવસાય શરૂ કરે છે. P એ Rs. 30,000નું રોકાણ કરે છે, Q એ Rs. 45,000નું રોકાણ કરે છે, R એ Rs. 60,000નું રોકાણ કરે છે, અને S એ Rs. 65,000નું રોકાણ કરે છે. Rs.40,000 ના નફામાંથી રોકાણકાર R ને કેટલો હિસ્સો મળશે?","options":{"A":"Rs.8,000","B":"Rs. 10,000","C":"Rs.12,000","D":"Rs. 15,000"},"correct_answer":"C","explanation":"P : Q : R : S ગુણોત્તર = 30 : 45 : 60 : 65 = 6 : 9 : 12 : 13.\nકુલ ભાગ = 6 + 9 + 12 + 13 = 40 ભાગ = Rs. 40,000 => 1 ભાગ = Rs. 1,000.\nR નો હિસ્સો (12 ભાગ) = 12 × 1,000 = Rs. 12,000.\nસાચો જવાબ: (C) Rs.12,000."},{"question_number":16,"source":"ભાગીદારી .pdf (Page 21, CCE 2023)","topic":"CCE 2023 - નફા પછી ખર્ચ અને બાકી ફંડનો કોયડો","question_text":"ચાર મિત્રો X Y Z અને W એક પ્રોજેક્ટમાં રોકાણ કરે છે. X ₹5000નું રોકાણ કરે છે, Y ₹10000નું રોકાણ કરે છે, Z ₹15000નું રોકાણ કરે છે અને W ₹20000નું રોકાણ કરે છે. પ્રોજેક્ટ ₹30000 નો નફો કમાય છે જે રોકાણકારોમાં તેમના રોકાણના પ્રમાણ અનુસાર વહેંચવામાં આવે છે. X નફાનો તેનો હિસ્સો મેળવે છે અને તેનો એક ભાગ ભાડા પર ખર્ચવાનું નક્કી કરે છે અને ભાડું અને બાકીનું ફંડ 2:3 ના ગુણોત્તરમાં છે. ખર્ચની આ પેટર્ન જોતાં, તેનું ભાડું ચૂકવ્યા પછી X પાસે કેટલી રકમ બાકી રહે છે?","options":{"A":"₹1800","B":"₹1500","C":"₹ 2400","D":"₹1200"},"correct_answer":"A","explanation":"X : Y : Z : W રોકાણનો ગુણોત્તર = 5 : 10 : 15 : 20 = 1 : 2 : 3 : 4.\nકુલ ભાગ = 1 + 2 + 3 + 4 = 10 ભાગ = ₹ 30,000 => 1 ભાગ = ₹ 3,000.\nતેથી X નો નફો = 1 ભાગ = ₹ 3,000.\nX પોતાના ₹ 3,000 ને ભાડું અને બાકીના ફંડ વચ્ચે 2 : 3 ના ગુણોત્તરમાં વહેંચે છે.\nકુલ ભાગ = 2 + 3 = 5 ભાગ = ₹ 3,000 => 1 ભાગ = ₹ 600.\nભાડું ચૂકવ્યા પછી બાકી રકમ (3 ભાગ) = 3 × 600 = ₹ 1,800.\nસાચો જવાબ: (A) ₹1800."},{"question_number":17,"source":"ભાગીદારી .pdf (Page 22)","topic":"રોકાણ અને નફાના ગુણોત્તર પરથી સમયગાળાનો ગુણોત્તર","question_text":"A, B અને C એક ધંધાની શરૂઆત 2 : 3 : 5 ના ગુણોત્તરમાં રોકાણ કરીને કરે છે જો ધંધાને અંતે તેમને થતા નફાનો ગુણોત્તર 5 : 3 : 12 હોય તો તેણે કરેલા રોકાણના સમયગાળા નો ગુણોત્તર શોધો.","options":{"A":"25:10:24","B":"5:2:4","C":"25:5:12","D":"5:10:12"},"correct_answer":"A","explanation":"સૂત્ર: સમયગાળાનો ગુણોત્તર = (નફાનો ગુણોત્તર) / (રોકાણનો ગુણોત્તર).\nસમય A : B : C = (5 / 2) : (3 / 3) : (12 / 5) = 2.5 : 1 : 2.4.\nદરેકને 10 વડે ગુણતાં = 25 : 10 : 24.\nસાચો જવાબ: (A) 25:10:24."},{"question_number":18,"source":"ભાગીદારી .pdf (Page 23)","topic":"સમય અને નફાના ગુણોત્તર પરથી રોકાણનો ગુણોત્તર","question_text":"A , B અને C ભાગીદારીમાં કોઈ ધંધાની શરૂઆત કરે છે જો તેના રોકાણના સમયગાળાનો ગુણોત્તર 5 : 6 : 8 હોય અને તેને મળતા નફાનો ગુણોત્તર 5 : 3 : 12 હોય તો રોકાણ નો ગુણોત્તર શોધો.","options":{"A":"2:3:1","B":"1:2:3","C":"3:2:1","D":"2:1:3"},"correct_answer":"D","explanation":"સૂત્ર: રોકાણનો ગુણોત્તર = (નફાનો ગુણોત્તર) / (સમયગાળાનો ગુણોત્તર).\nરોકાણ A : B : C = (5 / 5) : (3 / 6) : (12 / 8) = 1 : 1/2 : 3/2.\nદરેકને 2 વડે ગુણતાં = 2 : 1 : 3.\nસાચો જવાબ: (D) 2:1:3."},{"question_number":19,"source":"ભાગીદારી .pdf (Page 24, CCE 2023)","topic":"CCE 2023 - મૂડી અને સમય ગુણોત્તર પરથી નફાનો ગુણોત્તર","question_text":"એક ધંધામાં M, N, O જો 4 : 5 : 7ના ગુણોત્તરમાં મૂડીનું રોકાણ કરે અને તેઓના રોકાણનો સમયગાળો 3 : 5 : 6ના ગુણોત્તરમાં હોય તો નફો કયા ગુણોત્તરમાં વહેંચવો જોઈએ?","options":{"A":"12:25:42","B":"4:5:12","C":"3:25:7","D":"12:25:36"},"correct_answer":"A","explanation":"સૂત્ર: નફાનો ગુણોત્તર = (મૂડીનો ગુણોત્તર) × (સમયનો ગુણોત્તર).\nનફો M : N : O = (4 × 3) : (5 × 5) : (7 × 6) = 12 : 25 : 42.\nસાચો જવાબ: (A) 12:25:42."},{"question_number":20,"source":"ભાગીદારી .pdf (Page 25, CCE 2023)","topic":"CCE 2023 - અલગ અલગ મહિનાના રોકાણ પરથી નફો","question_text":"P, Q અને R ભાગીદારીમાં રોકાણ કરે છે. P આખા વર્ષ માટે ₹20,000નું રોકાણ કરે છે, Q 6 મહિના માટે ₹30,000નું રોકાણ કરે છે અને R 9 મહિના માટે ₹40,000નું રોકાણ કરે છે. જો વાર્ષિક નફો ₹78,000 છે, તો Q નો હિસ્સો કેટલો છે?","options":{"A":"₹15000","B":"₹12000","C":"₹ 18,000","D":"₹ 9000"},"correct_answer":"C","explanation":"P નું ગુણનફળ = 20,000 × 12 = 240,000\nQ નું ગુણનફળ = 30,000 × 6 = 180,000\nR નું ગુણનફળ = 40,000 × 9 = 360,000\nનફાનો ગુણોત્તર P : Q : R = 24 : 18 : 36 = 4 : 3 : 6.\nકુલ ભાગ = 4 + 3 + 6 = 13 ભાગ = ₹ 78,000 => 1 ભાગ = ₹ 6,000.\nQ નો હિસ્સો (3 ભાગ) = 3 × 6,000 = ₹ 18,000.\nસાચો જવાબ: (C) ₹ 18,000."},{"question_number":21,"source":"ભાગીદારી .pdf (Page 26, CCE 2023)","topic":"CCE 2023 - વર્ષોમાં આપેલા સમય પરથી નફાની ગણતરી","question_text":"A, B અને C એ એક બીઝનેશમાં અનુક્રમે Rs.5000, Rs.10000 અને Rs.15000 નું રોકાણ કર્યું છે. તેઓએ અનુક્રમે 2, 1 અને 3 વર્ષ માટે નાણાંનું રોકાણ કર્યું છે. જો કુલ નફો Rs.65000 છે, તો પછી નફામાં B નો હિસ્સો કેટલો છે?","options":{"A":"Rs. 45000","B":"Rs. 15000","C":"Rs. 10000","D":"Rs. 25000"},"correct_answer":"C","explanation":"મૂડીનો ગુણોત્તર A : B : C = 1 : 2 : 3.\nસમયનો ગુણોત્તર A : B : C = 2 : 1 : 3.\nનફાનો ગુણોત્તર A : B : C = (1×2) : (2×1) : (3×3) = 2 : 2 : 9.\nકુલ ભાગ = 2 + 2 + 9 = 13 ભાગ = Rs. 65,000 => 1 ભાગ = Rs. 5,000.\nB નો હિસ્સો (2 ભાગ) = 2 × 5,000 = Rs. 10,000.\nસાચો જવાબ: (C) Rs. 10000."},{"question_number":22,"source":"ભાગીદારી .pdf (Page 27, CCE 2023)","topic":"CCE 2023 - બે ભાગીદારોનો સંયુક્ત નફો","question_text":"સુરેશ, મુકેશ અને રોહન ભાગીદારી શરૂ કરે છે. તેઓએ અનુક્રમે Rs.8000, Rs.20000 અને Rs. 18000 રોકાણ કર્યું છે તેઓ ભાગીદારીમાં અનુક્રમે 4 મહિના, 8 મહિના અને 4 મહિના રહ્યા. જો કુલ નફો Rs. 132000 હોય, તો પછી નફામાં સુરેશ અને રોહનનો સંયુક્ત હિસ્સો કેટલો છે?","options":{"A":"Rs. 4500","B":"Rs. 91000","C":"Rs. 52000","D":"Rs. 78000"},"correct_answer":"C","explanation":"મૂડી S : M : R = 8 : 20 : 18 = 4 : 10 : 9.\nસમય S : M : R = 4 : 8 : 4 = 1 : 2 : 1.\nનફાનો ગુણોત્તર S : M : R = (4×1) : (10×2) : (9×1) = 4 : 20 : 9.\nકુલ ભાગ = 4 + 20 + 9 = 33 ભાગ = Rs. 132,000 => 1 ભાગ = Rs. 4,000.\nસુરેશ + રોહન સંયુક્ત હિસ્સો (4 + 9 = 13 ભાગ) = 13 × 4,000 = Rs. 52,000.\nસાચો જવાબ: (C) Rs. 52000."},{"question_number":23,"source":"ભાગીદારી .pdf (Page 28, CCE 2023)","topic":"CCE 2023 - વચ્ચેથી નાણાં ઉમેરવા અને ઉપાડવાના કઠિન પ્રશ્નો","question_text":"A, B અને C Rs. 36,000 પ્રત્યેક રોકાણ કરીને ભાગીદારીમાં જોડાય છે. 4 મહિના પછી, A Rs. 10,800 નો ઉપાડ કરે છે. B એ Rs. 14,400 નો ઉપાડ કરે છે અને Cએ Rs.10,800 વધુનું રોકાણ કરે છે. વર્ષના અંતે, કુલ નફો Rs. 118080 થાય છે. તો તેમાં C નો ભાગ શોધો.","options":{"A":"Rs. 51840","B":"Rs. 34560","C":"Rs. 77760","D":"Rs. 38880"},"correct_answer":"A","explanation":"દરેકની શરૂઆતની મૂડી = 36,000 (360 અંક ગણીએ).\nA નો ગુણાંક = (360 × 4) + ((360 - 108) × 8) = 1440 + (252 × 8) = 1440 + 2016 = 3456.\nB નો ગુણાંક = (360 × 4) + ((360 - 144) × 8) = 1440 + (216 × 8) = 1440 + 1728 = 3168.\nC નો ગુણાંક = (360 × 4) + ((360 + 108) × 8) = 1440 + (468 × 8) = 1440 + 3744 = 5184.\nનફાનો ગુણોત્તર A : B : C = 3456 : 3168 : 5184 = 12 : 11 : 18.\nકુલ ભાગ = 12 + 11 + 18 = 41 ભાગ = Rs. 118080 => 1 ભાગ = Rs. 2880.\nC નો ભાગ (18 ભાગ) = 18 × 2880 = Rs. 51840.\nસાચો જવાબ: (A) Rs. 51840."},{"question_number":24,"source":"ભાગીદારી .pdf (Page 29)","topic":"મોડેથી જોડાનાર ભાગીદારનો નફાનો ગુણોત્તર","question_text":"A, ₹ 2000 સાથે કોઈ ધંધાની શરૂઆત કરે છે અને B, 3 મહિના પછી ₹ 8000 લઈને A સાથે ભાગીદારીમાં જોડાય છે તો 1 વર્ષ પછી તેને થતા નફાનો ગુણોત્તર શોધો.","options":{"A":"3:1","B":"1:3","C":"1:2","D":"2:1"},"correct_answer":"B","explanation":"A નું રોકાણ = ₹ 2000 આખા 12 મહિના માટે => 2000 × 12 = 24,000.\nB 3 મહિના પછી જોડાય છે, તેથી B નો સમય = 12 - 3 = 9 મહિના => 8000 × 9 = 72,000.\nનફાનો ગુણોત્તર A : B = 24,000 : 72,000 = 1 : 3.\nસાચો જવાબ: (B) 1:3."},{"question_number":25,"source":"ભાગીદારી .pdf (Page 30)","topic":"મોડેથી જોડાનાર ભાગીદારનો નફો","question_text":"A, ₹ 4000 સાથે કોઈ ધંધાની શરૂઆત કરે છે અને B, 4 મહિના પછી ₹ 5000 લઈને A સાથે ભાગીદારીમાં જોડાય છે જો 1 વર્ષ પછી તેને થતો કુલ નફો ₹ 22000 હોય તો B ને થતો નફો શોધો.","options":{"A":"₹ 8000","B":"₹ 10000","C":"₹ 11000","D":"₹ 12000"},"correct_answer":"B","explanation":"A નો ગુણનફાળો = 4000 × 12 = 48,000.\nB નો ગુણનફાળો = 5000 × (12 - 4) = 5000 × 8 = 40,000.\nનફાનો ગુણોત્તર A : B = 48 : 40 = 6 : 5.\nકુલ ભાગ = 6 + 5 = 11 ભાગ = ₹ 22,000 => 1 ભાગ = ₹ 2,000.\nB નો નફો (5 ભાગ) = 5 × 2,000 = ₹ 10,000.\nસાચો જવાબ: (B) ₹ 10000."},{"question_number":26,"source":"ભાગીદારી .pdf (Page 31)","topic":"વર્ષ અને મહિનાનું રૂપાંતરણ","question_text":"રાકેશ અને વિજય એક વ્યવસાયમાં ભાગીદાર છે રાકેશ ₹ 64000 1.5 વર્ષ માટે અને વિજય ₹ 72000 15 મહિના માટે રોકે છે તો કુલ નફો ₹ 9300 થતો હોય તો તેમાં વિજયનો ભાગ કેટલો હશે.","options":{"A":"₹ 4500","B":"₹ 5400","C":"₹ 6200","D":"એક પણ નહીં"},"correct_answer":"A","explanation":"રાકેશનો સમય = 1.5 વર્ષ = 18 મહિના.\nવિજયનો સમય = 15 મહિના.\nરાકેશ ગુણનફાળો = 64,000 × 18 = 1,152,000 (અથવા 64 × 18).\nવિજય ગુણનફાળો = 72,000 × 15 = 1,080,000 (અથવા 72 × 15).\nરાકેશ : વિજય = (64 × 18) : (72 × 15) = (64) : (4 × 15) = 64 : 60 = 16 : 15.\nકુલ ભાગ = 16 + 15 = 31 ભાગ = ₹ 9300 => 1 ભાગ = ₹ 300.\nવિજયનો ભાગ (15 ભાગ) = 15 × 300 = ₹ 4,500.\nસાચો જવાબ: (A) ₹ 4500."},{"question_number":27,"source":"ભાગીદારી .pdf (Page 32)","topic":"અલગ અલગ સમયગાળાના ૩ ભાગીદારો","question_text":"ત્રણ મિત્રો એક વેપાર શરૂ કરે છે જેમાં રમેશ 4 મહિના માટે ₹ 10,000 સુરેશ 6 મહિના માટે ₹ 5000 અને મહેશ 5 મહિના માટે ₹ 16000 રોકે છે જો એક વર્ષના અંતે થતો કુલ નફો ₹ 4500 હોય તો રમેશના ભાગે કેટલો નફો આવશે.","options":{"A":"₹ 1200","B":"₹ 900","C":"₹ 2400","D":"એક પણ નહીં"},"correct_answer":"A","explanation":"રમેશ (R) = 10,000 × 4 = 40,000.\nસુરેશ (S) = 5,000 × 6 = 30,000.\nમહેશ (M) = 16,000 × 5 = 80,000.\nનફાનો ગુણોત્તર R : S : M = 4 : 3 : 8.\nકુલ ભાગ = 4 + 3 + 8 = 15 ભાગ = ₹ 4500 => 1 ભાગ = ₹ 300.\nરમેશનો નફો (4 ભાગ) = 4 × 300 = ₹ 1,200.\nસાચો જવાબ: (A) ₹ 1200."},{"question_number":28,"source":"ભાગીદારી .pdf (Page 33)","topic":"નફાના ગુણોત્તર પરથી પ્રથમ ભાગીદારનું રોકાણ શોધો","question_text":"5 મહિના પહેલા A અને B ભાગીદારીમાં ધંધો શરૂ કરે છે A અને B ને મળતા નફાનો ગુણોત્તર 6 : 17 છે,જો B એ આ ધંધાની શરૂઆત 12 મહિના પહેલા ₹ 1275 રોકાણ સાથે કરી હોય તો A નું રોકાણ શોધો.","options":{"A":"₹ 840","B":"₹ 960","C":"₹ 1080","D":"₹ 1200"},"correct_answer":"C","explanation":"ધારો કે A નું રોકાણ = x.\nA ધંધામાં 5 મહિના રહ્યો => A નો સમય = 5.\nB નું રોકાણ = ₹ 1275, B નો સમય = 12 મહિના.\nનફાનો સમીકરણ: (x × 5) / (1275 × 12) = 6 / 17.\n5x / 15300 = 6 / 17 => 5x = (6 × 15300) / 17 = 6 × 900 = 5400.\nx = 5400 / 5 = ₹ 1080.\nA નું રોકાણ = ₹ 1080.\nસાચો જવાબ: (C) ₹ 1080."},{"question_number":29,"source":"ભાગીદારી .pdf (Page 34)","topic":"નફાના ગુણોત્તર પરથી બીજા ભાગીદારની મૂડી શોધો","question_text":"વ્યક્તિ A ₹7,000 રોકીને ધંધો શરૂ કરે છે તેના 5 મહિના પછી B ભાગીદાર તરીકે જોડાય છે 1 વર્ષ પછી મળેલ નફો 2:3 ના ગુણોત્તરમાં વહેંચવામાં આવે તો વ્યક્તિ B ની મૂડી કેટલા રૂપિયા હશે.","options":{"A":"₹ 20000","B":"₹ 16000","C":"₹ 22000","D":"₹ 18000"},"correct_answer":"D","explanation":"A ની મૂડી = 7000, A નો સમય = 12 મહિના.\nB ની મૂડી = x, B નો સમય = 12 - 5 = 7 મહિના.\nનફાનો ગુણોત્તર: (7000 × 12) / (x × 7) = 2 / 3.\n84000 / 7x = 2 / 3 => 12000 / x = 2 / 3 => 2x = 36000 => x = ₹ 18,000.\nવ્યક્તિ B ની મૂડી = ₹ 18,000.\nસાચો જવાબ: (D) ₹ 18000."},{"question_number":30,"source":"ભાગીદારી .pdf (Page 35)","topic":"જોડાવાનો સમય (મહિના) શોધો","question_text":"A, ₹ 76000 નું રોકાણ કરીને કોઈ ધંધાની શરૂઆત કરે છે થોડા મહિના પછી B, ₹ 57000 નું રોકાણ કરી A સાથે ધંધામાં જોડાય છે. વર્ષના અંતે A અને B ને થતા નફાનો ગુણોત્તર 2 : 1 હોય તો B કેટલા મહિના પછી A સાથે ધંધામાં જોડાયો હશે.","options":{"A":"8","B":"3","C":"9","D":"4"},"correct_answer":"D","explanation":"A નો સમય = 12 મહિના, રોકાણ = 76,000 (19 વડે ભાગતાં = 4).\nB નું રોકાણ = 57,000 (19 વડે ભાગતાં = 3), સમય = t મહિના.\nનફાનો ગુણોત્તર: (76000 × 12) / (57000 × t) = 2 / 1.\n(4 × 12) / (3 × t) = 2 / 1 => 48 / 3t = 2 / 1 => 16 / t = 2 => t = 8 મહિના (રોકેલો સમય).\nB જોડાયો તે સમય = 12 - 8 = 4 મહિના પછી.\nસાચો જવાબ: (D) 4."},{"question_number":31,"source":"ભાગીદારી .pdf (Page 36)","topic":"રોકાણ અંકુશ સમય શોધો","question_text":"A અને B 5:6 ના ગુણોત્તરમાં મૂડી રોકાણ કરીને એક ધંધો શરૂ કરે છે 8 મહિના પછી A પોતાની મૂડી પાછી લઈ લે છે જો તેઓનો નફાનો ગુણોત્તર 5:9 હોય તો B એ કેટલા મહિના સુધી પોતાની મૂડી રોકેલી હશે.","options":{"A":"8","B":"9","C":"11","D":"12"},"correct_answer":"D","explanation":"A નું રોકાણ = 5, સમય = 8 મહિના.\nB નું રોકાણ = 6, સમય = t મહિના.\nનફાનો ગુણોત્તર: (5 × 8) / (6 × t) = 5 / 9.\n40 / 6t = 5 / 9 => 40 × 9 = 30t => 360 = 30t => t = 12 મહિના.\nB એ 12 મહિના સુધી પોતાની મૂડી રોકેલી હશે.\nસાચો જવાબ: (D) 12."},{"question_number":32,"source":"ભાગીદારી .pdf (Page 37)","topic":"બમણી અને ત્રણ ગણી મૂડી સાથે વચ્ચેથી જોડાતા ભાગીદારો","question_text":"A, B અને C ભેગા થઈને ધંધો શરૂ કરે છે. A નિશ્ચિત રકમનું મૂડી રોકાણ કરે છે. છ મહિના પછી B એ A કરતાં બમણી રકમનું મૂડી રોકાણ કરે છે. આઠ મહિના પછી C એ A કરતાં ત્રણ ગણી રકમનું મૂડી રોકાણ કરે છે તો વર્ષના અંતે કુલ નફો ₹ 36,000 હોય તો C ને મળતો નફો શોધો.","options":{"A":"₹ 12000","B":"₹ 9002","C":"₹ 9287","D":"₹ 9820"},"correct_answer":"A","explanation":"ધારો કે A ની મૂડી = 1, સમય = 12 મહિના => A નો ગુણનફાળો = 1 × 12 = 12.\nB 6 મહિના પછી જોડાય છે, મૂડી = 2, સમય = 12 - 6 = 6 મહિના => B નો ગુણનફાળો = 2 × 6 = 12.\nC 8 મહિના પછી જોડાય છે, મૂડી = 3, સમય = 12 - 8 = 4 મહિના => C નો ગુણનફાળો = 3 × 4 = 12.\nનફાનો ગુણોત્તર A : B : C = 12 : 12 : 12 = 1 : 1 : 1.\nકુલ નફો = ₹ 36,000 માં C નો ભાગ (1/3) = 36,000 / 3 = ₹ 12,000.\nસાચો જવાબ: (A) ₹ 12000."},{"question_number":33,"source":"ભાગીદારી .pdf (Page 38)","topic":"વચ્ચેથી નાણાં ઉમેરવા/ઉપાડવા વાળા ૩ ભાગીદારોનો નફો","question_text":"A, B અને C એક ધંધો ચાલુ કરે છે જેમાં દરેક ₹ 20,000 નું રોકાણ કરે છે. 5 મહિના પછી A ₹ 5000 કાઢી લે છે B ₹ 4000 કાઢી લે અને C ₹ 6000 ઉમેરે છે તો વર્ષના અંતે કુલ નફો ₹ 69,900 થતો હોય તો B ને થતો નફો શોધો.","options":{"A":"₹ 21200","B":"₹ 28200","C":"₹ 20500","D":"એક પણ નહીં"},"correct_answer":"A","explanation":"દરેકની શરૂઆતની મૂડી = 20 (હજારમાં).\nA નું કુલ મૂડી-સમય = (20 × 5) + (15 × 7) = 100 + 105 = 205.\nB નું કુલ મૂડી-સમય = (20 × 5) + (16 × 7) = 100 + 112 = 212.\nC નું કુલ મૂડી-સમય = (20 × 5) + (26 × 7) = 100 + 182 = 282.\nનફાનો ગુણોત્તર A : B : C = 205 : 212 : 282.\nકુલ ભાગ = 205 + 212 + 282 = 699 ભાગ = ₹ 69,900 => 1 ભાગ = ₹ 100.\nB નો નફો (212 ભાગ) = 212 × 100 = ₹ 21,200.\nસાચો જવાબ: (A) ₹ 21200."}]};
